local quests = pack.locales.enUS

quests[84848] = { id = 84848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Void", description = "You've impressed these Wastelanders with your violent prowess, my champion. Well done. Now let me do my work.\n\nI know what these former oracles want. They dream of hearing the Song of K'aresh once more. I must make them believe it is possible, then pull on that string of desire. Soon we will have our army, and another Reshii Ribbon.\n\nFirst, let's return the Tabiqa ritual dagger.", completion = "We would gladly war against the Shadowguard. But I cannot give up this Reshii Ribbon to someone I don't trust.\n\nPromises of revenge are easy. Trust is hard won among the Wastelanders.", objectives = "Convince Soul-Scribe to join forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84850] = { id = 84850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serpent's Wrath" }
quests[84851] = { id = 84851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tides of Greed" }
quests[84852] = { id = 84852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the Vrykul" }
quests[84855] = { id = 84855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Silence", description = "Dimensius's power is so great that even shattered, his aura radiates a power debilitating to mortal life. It is why the K'areshi were changed to beings of energy--it was the only way we could survive his presence.\n\nI had hoped my scouts could find a path that was safe for you and your compatriots to enter the manaforge. Raz'ida, Lo'shah, and Yanhal should have met us by now. Find them for me. Their information is vital to our defense against the All-Devouring.", completion = "Raz'ida was a Shadowguard agent? I've trusted her for thousands of years. How did they break her loyalty? \n\nIf she could be turned, then any of the Trust's agents could as well. It is vital that we get the information about their base, and we can only rely upon the four of us to do so.", objectives = "Find the scouts at Overlook Zo'Shuul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84856] = { id = 84856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where the Void Gathers", description = "With Locus-Walker's Reshii Ribbon, I can transmute your flesh to energy. It won't hurt much.\n\nYou will have the ability to travel within Dimensius's aura without being destroyed. There you can search for a path into the manaforge. You will travel in Untethered Space as a creature of energy, ignored by the Shadowguard. Their void beasts however... stay well away or be devoured. \n\nTalk to me when you are ready. Time is of the essence.", progress = "We will need more than one Reshii Ribbon if we want to reach Dimensius with a force capable of stopping his emergence.", completion = "Through this, you have learned what I already knew. \n\nDimensius is a terrible threat. We must work together, {name}, if we are to survive.", objectives = "Search Shadow Point in Untethered Space with Xal'atath's help.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84857] = { id = 84857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eco-Dome: Primus", description = "Xal'atath is correct. We need more than my one Reshii Ribbon to get a force to Dimensius. \n\nThere is an eco-dome south of here. The founder of the Trust is there, overseeing its operation. She acquired the domes from the Consortium. She claims they will be the key to restoring K'aresh. I am skeptical anything will be safe now that Dimensius stirs. \n\nShe was a member of the Ravel and possesses a Reshii Ribbon. Surely she would lend it to us.", completion = "The Shadowguard attacked the eco-dome. They must covet the vast stores of energy needed to shield the delicate biomes from the Void of K'aresh.", objectives = "Meet Locus-Walker at Eco-Dome: Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84858] = { id = 84858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "System Restart", description = "My Reshii Ribbon is all that is keeping this dome and its systems from collapsing.\n\nThis eco-dome took too much of my fortune to build just for the Shadowguard to destroy it. They have sabotaged many of our control consoles, risking a complete ecological collapse.\n\nFind Engineer Om'loof and help him restart our environmental support system while I monitor the rest of the facility.", progress = "This eco-dome will fail if the environmental support system stops. We must stabilize it!", completion = "Environmental support may be back up and running, but don't get complacent. That was merely the first of the many problems plaguing this eco-dome.", objectives = "Help Engineer Om'loof in Eco-Dome: Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84859] = { id = 84859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damage Report 101", description = "Just like Engineer Om'loof, I have hired more well-regarded, highly trained, expensive management consultants from cartel Om. Two of them have not reported in. Are they dead, or just distracted again? \n\nFind botanist Om'nittar and shield technician Om'door. Get their damage reports. I need to know if the attack caused any lasting damage to my dome.", progress = "I hire the best. I am sure Om'nittar and Om'door have the information I need.", completion = "Are they alive? Good. Next time they forget to check in, they won't be.\n\n<Ve'nari skims through the reports.>\n\nIt looks like there was minimal damage, if any at all, to most of the facility. The Shadowguard saboteurs were focused on rerouting our energy reserves to the outer conduits. They have ignored the environmental and secondary systems.", objectives = "Find botanist Om'nittar and shield technician Om'door and bring their reports to Ve'nari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84860] = { id = 84860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eco-Stabilizing", description = "The Shadowguard attack caused chaos and disarray in this dome. Several control consoles have powered down, and my consultants are stretched thin reviving their assigned biomes and systems.\n\nThis is where you come in, {name}. It's an easy, but critical job. Find the disabled consoles and make sure they restart.", progress = "Are all the consoles operational? No? Go switch them on!", completion = "Good work, {name}.\n\nThe interior of the dome is stabilized. All the eco-dome systems are functioning. My investment in the eco-domes will continue to pay dividends. Unless the Shadowguard attack again.", objectives = "Activate the disabled control consoles in Eco-Dome: Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84861] = { id = 84861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Is Our Dome!", description = "We may have driven the saboteurs out of the dome and repaired its systems, but that doesn't mean the Shadowguard is done with my domes. They're still hiding at the perimeter, trying to find a way to harvest the vast amounts of expensive energy needed to power the eco-dome.\n\nI need you to fight them off. Then maybe this attack will truly end.", progress = "Did you get them all? Or are there still Shadowguard hiding around the perimeter, damaging my dome?", completion = "Good. That will buy us enough time to secure this dome.", objectives = "Kill 7 Shadowguard around Eco-Dome: Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84862] = { id = 84862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Alliance", description = "We can't have you patrolling the perimeter of this dome, like the city watch fighting attackers in perpetuity. We need a permanent solution so we can continue with our noble quest.\n\nTake these crystals. They've been attuned to the eco-dome's defense magics. Just place them near strategic parts of the perimeter to strengthen the magical defenses.\n\nWhat? This time it's no trick. If this dome explodes, I'll never get to destroy Dimensius.", progress = "Have you placed the crystals I gave you? Ve'nari won't give up her ribbon until her dome is secure.", completion = "That should secure this dome. But will Ve'nari make us float through any more hoops?", objectives = "Place 4 Xal'atath defenses around Eco-Dome: Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84863] = { id = 84863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Counter Measures", description = "I cannot relinquish my Reshii Ribbon just yet, {name}. Not while the Shadowguard assaults my eco-dome from their camp in Serrated Peaks. Take the fight to them! If you decimate their forces, they will stop this assault. \n\nBring Locus-Walker's apprentice, Alleria. She looks like she knows how to handle herself in a fight. She also keeps staring daggers at the Harbinger, and I don't have time to play peacemaker between those two.", progress = "The Shadowguard are still attacking. Did you decimate their numbers yet?", completion = "Good job, {name}. That should satisfy Ve'nari.", objectives = "Kill 12 Shadowguard forces in Serrated Peaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84864] = { id = 84864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her Dark Side", description = "An ethereal army runs on its energy siphons. Interrupt the flow of energy by destroying their siphon tower, and the army will pull back. It's one of their weaknesses as minions. Normally I wouldn't share the secrets of their defeat, but they betrayed me and will forever live with the consequences.\n\nThe siphon has a control console that can be overloaded to collapse the system. It will be shielded by a void barrier. Alleria can remove it for you.", progress = "Now the Shadowguard will have to retreat.", completion = "I feel like there is something Locus-Walker and Ve'nari are keeping from me. Some secret during the Devouring War that they don't want me to know. Xal'atath is pulling on this doubt to manipulate me. \n\nLet's defeat the Shadowguard, then we can uncover the truth.", objectives = "Destroy the Ethereal Siphon in Serrated Peaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84865] = { id = 84865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divide and Conquer", description = "Of all the assets on the field of battle, the troops are the most expendable. I've sent enough to their destruction to know this as a fact. If we are to safeguard this dome for Ve'nari and get her Reshii Ribbon, we should destroy their cannons.\n\nThose cannons are easily worth the lives of all of their soldiers. Destroy them and their commanders will sound the retreat. Most field commanders would never admit this as it's bad for morale, but you seem like the type that can handle uncomfortable truths.", progress = "Taking out these cannons will force the Shadowguard's retreat. I would not listen to Xal'atath's ideas on ethics of command, though.", completion = "Without their cannons, the Shadowguard's attacks on the eco-dome are doomed to failure. Ve'nari won't have need of her Reshii Ribbon. \n\nI'm more and more unsettled by this plan of ours, though--the secrets... this Alliance with Xal'atath... I fear Locus-Walker made a mistake thousands of years ago, and we cannot escape that ancient mistake.", objectives = "Destroy 3 Shadowguard Cannons in Serrated Peaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84866] = { id = 84866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Purchase Safety", description = "I need to focus on the mission. Regardless of my doubts about our companions, the Shadowguard are a scourge. We should slay their Shadow-Captain so they cannot easily return to Eco-Dome: Primus. Ve'nari would lend her Reshii Ribbon to our cause, and we would discover if my trust in Locus-Walker was well placed.\n\nI will not let my doubts stay my bow on the battlefield, {name}. You can trust me to hunt these followers of Dimensius.", completion = "With that necessary violence taken care of, the three of us can talk. You are correct, Alleria. Great secrets have been kept from you. Secrets that were not mine to reveal but should have been revealed to you years ago.", objectives = "Kill Shadow-Captain Lakheesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84867] = { id = 84867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalking Stalkers", description = "I've planted the seed, yet Soul-Scribe still hesitates. Her daughter Narathe is more receptive. She might be able to give us the nudge that's needed to win the Wastelanders over. Daughters are useful.\n\nGo with Narathe. Win over their tribe. I will stay here and continue to work on Soul-Scribe's will.", progress = "I will do what my oaths dictate, but I am not convinced that your plan is the way to go.", completion = "Word has filtered up through my camp about what you have done for us. My daughter has always been too trusting, but your efforts do not go unnoticed.", objectives = "Find a way to sway the Wastelanders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84868] = { id = 84868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Whiff of Help", description = "You seem quite equipped for solving secrets now! As much as I expect Maru would want to come with you, she's far too young.\n\nFortunately, we Tuskarr have an incense that lets our souls communicate across long distances.\n\nI keep a stock of it on me if you need. As a friend of Maru, I will only charge you for the cost of materials.", progress = "Have you tried the incense?", completion = "Now you see the power of our spiritual connections.\n\nHere, take a few with you.", objectives = "Purchase and use a Spiritual Incense from Benatauk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84869] = { id = 84869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting on Glass", description = "Violent scavengers of the Void have been drawn to Dimensius's aura to feast upon the scraps he will leave behind. This presents a problem for our Wastelander friends. Scavenging is their job.\n\nThey could handle these beasts--I would not be seeking to ally with them if they couldn't. But why not give them a gift, and show them you are their equal--no, their superior in combat?", progress = "Dimensius's power grows and the Wastelanders are feeling the pinch. Let us ease the pressure for them a bit.", completion = "These Wastelanders respect strength and violence. I think we're going to get along quite well.", objectives = "Kill 4 Void Terrors and 8 Unreal Observers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84876] = { id = 84876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Oasis", description = "Soul-Scribe would fight for us, even die for our cause. Yet she still denies us her Reshii Ribbon. She sees it as a tool of the Ravel, and her oaths are getting in the way of our mission.\n\nIf she could feel the presence of the Worldsoul K'aresh once again, she would give anything to protect him--even the ribbon. The Oasis is the Trust's eco-dome that has a stable biome. The perfect place to commune with a Worldsoul, if one still exists.", progress = "Our research here is essential to the future of K'aresh. That we have stabilized this area means that we can replicate this feat in other domes--perhaps even heal the shattered remains of K'aresh.", completion = "This is most irregular. Ve'nari may have asked that we extend all courtesy to the Harbinger and her champion. But these Wastelander barbarians? \n\nI hope Ve'nari knows what she's doing.", objectives = "Meet Xal'atath at the Oasis eco-dome.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84879] = { id = 84879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Hope", description = "This dome is a reasonable facsimile of K'aresh. We will find no better place for Soul-Scribe to hear the Worldsoul's song. \n\nAnd yet, as Dimensius grows in power, even the Oasis succumbs to the Void. I can feel the rifts tearing open. Their energies will disrupt this delicate ritual. Unfortunately they'll need to be closed so Soul-Scribe can be convinced.", progress = "The Void creeps further and further into K'aresh every day. Dimensius's power grows ever stronger.", completion = "We have a lot riding on this Tabiqa ritual going exactly to plan. Having to kill her to get her ribbon would be inconvenient.", objectives = "Cleanse the eco-dome of invasive elements.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84882] = { id = 84882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deck Dismay", description = "Gather up the cards that got scattered around the area and I will be forever grateful!", progress = "How's it going? Have you found all my missing cards?", completion = "You've found them all? Thank you so much! I'm forever in your debt!", objectives = "Collect the missing cards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84883] = { id = 84883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "K'aresh That Was", description = "The Tabiqa has not been attempted for thousands of years. It was clear that the Devouring War destroyed K'aresh.\n\nAnd yet, looking at this dome... they have recreated so much that I thought lost forever--fresh water, clean air, even the zaranit flowers I thought extinct. Does the Harbinger speak the truth?\n\nNo. I didn't break my oath and abandon the Worldsoul. K'aresh is gone.", progress = "Did you find the components for the Tabiqa ritual? Do they even still exist?", completion = "To hold these blossoms in my hands again... I never thought I would see the day.", objectives = "Gather materials for the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84885] = { id = 84885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Working for G.E.T.A.", description = "Attention: Protect the Citizens of Undermine AND get paid!\n\nProfit-seeking bounty hunters encouraged to check in at the local G.E.T.A. office for more information.", progress = "Do you need something, {name}? I don't have time for idle chit-chat.", completion = "Both G.E.T.A. and the citizens of Undermine are willing to pay for your services and your discretion.", objectives = "Inquire at the local G.E.T.A. office in the Vatworks", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84891] = { id = 84891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "G.E.T.A. The Radioactive Rat", description = "We got a report here of some big, radioactive rat that was chased into a nearby sewer. Not only is it highly aggressive, it's terrible for the environment.\n\nHey, don't look at me like that. Us Underminers care about that stuff even if the big cartels don't.\n\nI put the location of the sewer entrance on your map. Hopefully, one of these lunks will get off their butts and join you there.", progress = "Once you're finished, come back here, and I'll make sure you're adequately compensated.", completion = "I haven't seen a rat that big since... actually, I don't think I've seen a rat that big before. Well done.", objectives = "Defeat the Radioactive Rat", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84892] = { id = 84892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "G.E.T.A. The Crocodilian", description = "Did you know that crocodiles can grow indefinitely?\n\nWell, the owner of this crocodile didn't. And when it got too big, it was released. Normally these crocodiles make their way out of the Undermine. But this one decided it liked the taste of goblins and stayed.\n\nIf you're up for it, the people of Undermine could use someone brave to face it. Are you game?", progress = "Who's afraid of a big ol' croc, you say?", completion = "It's done then. The people of Undermine won't realize what you did, but I do. Thanks from all of us.", objectives = "Defeat the Crocodilian", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84893] = { id = 84893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "G.E.T.A. The Captain", description = "This is a unique one. \n\nSome cave skippers got into the Undermine sewers and are starting to populate, causing all sorts of problems. It looks like an especially big one is organizing them somehow.\n\nWe've taken to calling him \"the Captain.\"\n\nMake sure his reign of finned, eye-bulging terror ends today.", progress = "Be careful, {name}. From what we can tell, The Captain doesn't work alone.", completion = "I've never thought of cave skippers as overly dangerous or organized. Looks like there's a lot about them we don't know.", objectives = "Defeat the Captain", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84894] = { id = 84894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "G.E.T.A. 2" }
quests[84896] = { id = 84896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Next Dimension", description = "By the Songs of K'aresh, I will join you to face the Shadowguard and Dimensius in battle. Let those that would prey on Untamed K'aresh fear his followers!\n\nMy scouts have tracked your comrades setting a foothold in Shadowguard territory. They will need our assistance. \n\nK'aresh lives! Our cause is just! Our oaths are unbroken!", completion = "I did not know there were this many void-touched from your world. How do they shield their souls from its madness?", objectives = "Meet with Soul-Scribe in Shan'dorah on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84897] = { id = 84897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Calm Before We Storm", description = "Narathe is right. We are fortunate that void elves have experience battling the Shadowguard. The wastes of K'aresh are merciless, and the battle to come will be as well. I hope they are prepared for a brutal fight. These will not be the scattered scouts they are used to fighting on Telogrus.\n\nYou should ensure they are ready for the battle to come.", progress = "We have spent a long time preparing for this moment. I will not let it slip.", completion = "These elves are more resilient than I thought. Perhaps our people have both been tempered by adversity?", objectives = "Check in with Alleria and the void elves at Shan'dorah on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84898] = { id = 84898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sands of K'aresh", description = "My people have fought across every inch of the ruins of our world. We gave our oath to King Salhadaar and he rewarded us by sending the Shadowguard to hunt us down.\n\nSalhadaar is long dead, but we knew the Shadowguard would return. In the long years that followed, we secreted caches of weapons so we would always be able to raise a blade in defiance.", progress = "Have you gathered all of the weapons caches in the sand?", completion = "These will do. They are still as sharp as ever. I will arm my people and your allies. For K'aresh, {name}.", objectives = "Collect 3 Weapons Caches from the nearby sands of the Shatter Gorge on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84899] = { id = 84899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowguard Diffusion", description = "With or without Xal'atath, the Shadowguard have long been a thorn in my side. It would be wise to take out as many as we can on this rock. I still do not trust her, but we must focus on the enemy we can defeat right now.\n\nDo not relent, {name}. If you see any Shadowguard, cut them down. A battle against them today saves us a battle against them tomorrow.", progress = "We still have many to defeat before we can progress.", completion = "Well done, {name}. If the Shadowguard bled, I am certain the sands would be soaked.\n\nMany more lay before us on the path to victory. There will be time for celebrations yet.", objectives = "Defeat Shadowguard in the sands of the Shatter Gorge surrounding Shan'dorah on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84900] = { id = 84900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like a Knife Through Aether", description = "Very good, my champion. You are a swift and sharp blade of destruction.\n\nWe will put all that power to use now. We will slaughter the Shadowguard that seek to raise Dimensius, and the machines created to feed his insatiable hunger. \n\nThe Shadowguard must have a Reshii Ribbon among their spoils. As we destroy their garrisons, look for this final ribbon. It is our way forward to kill a Void Lord.", progress = "A few more of these and we might even have a chance. Do not relent, {name}. You are capable of this and so much more.", completion = "Two more to go. Two more places for the ribbon to be hidden.", objectives = "Stop the Shadowguard ethereals at Shadow Point: Darkmend in K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84902] = { id = 84902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adverse Instantiation", description = "Turning into beings of energy was a choice we made when we had no other option. In the time since then, we have become reliant on consuming energy to survive. \n\nThe Shadowguard are feeding that power to Dimensius. His hunger is infinite, and he will drain the energy from K'aresh to fuel his re-emergence. We must destroy this machinery that feeds him, {name}.", progress = "Are they all dealt with?", completion = "My people's technomancy could be put to great and beneficial use, yet time and time again we use it for great evil. As Dimensius's power grows, we are all diminished.", objectives = "Disable 6 Shadowguard Power Pylons in Shadow Point on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84903] = { id = 84903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Until the Sands Bleed Void", description = "I have fought Shadowguard on Eredath, Telogrus, and now on K'aresh. They are a thorn that should be plucked from the cosmos.\n\nThat they should follow the very monster that threatened their world proves they are a scourge. Though, perhaps I am no better, fighting alongside Xal'atath. \n\nI will grapple with that contradiction later. For now, I intend for us to put an end to them, {name}.", progress = "Spare no remorse for their kind. They would do far worse.", completion = "Is this the fate of the ren'dorei? Given long enough, will we too serve the very forces we fight today? I had always looked to Locus-Walker as an example we can emulate, but it appears the ren'dorei must find their own path.", objectives = "Kill Shadowguard in Shadow Point on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84904] = { id = 84904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And We Will Answer", description = "This is unthinkable. Heretical!\n\nThe Shadowguard have captured my warriors and are converting them into new troops for Dimensius--forcing an oath to serve the All-Devouring as the Void fills their being.\n\nFree them, {name}. We cannot let this last any longer. I will send Narathe to aid you in this fight. She knows how to untether the souls of oath-breakers.", progress = "Once an ethereal embraces the shadow, they are lost forever.", completion = "How many were lost, do you think?\n\nI have a duty to my people. Let us finish this so none are forced to serve the All-Devouring again.", objectives = "Rescue Captured Wastelanders in Shadow Point on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84905] = { id = 84905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Walk Among Shadow", description = "We must continue disabling or destroying these buildings. I am loathe to destroy the technology of my people, but when used for such dire purpose, there is no choice!\n\nFrom here on out, hold nothing back. Let us raze the works of the Shadowguard.", completion = "There is only more darkness ahead of us. Be prepared for anything.", objectives = "Help Locus-Walker disable Shadow Point: Torment at Shadow Point on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84906] = { id = 84906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nexus Regicide", description = "Now is the time, {name}.\n\nWe must not hesitate. They will send their strongest to defend this last manaforge. We will find Nexus-Prince Azir there and we will end him before we take this battle to Dimensius. Xal'atath or no Xal'atath, we have what we need to do this. Just one final kill. \n\nLet us not dally. Make haste.", completion = "Hmmph.\n\nI grow tired of this lesson, {name}. Always when we get close to someone they betray us. They falter. They turn. They die. Always we put them in danger and we fail to protect them.\n\nLet no one else stand in our path. You and me, {name}. We will finish this.", objectives = "Defeat the leader of the Shadowguard in Shadow Point: Apotheosis on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84908] = { id = 84908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormrider's Honors", description = "<A golden missive finds its way to you.>\n\nChampion, though you are no Stormrider, you may yet be worthy of the Stormrider's armor.\n\nFind Stormrider Bruelda if you wish to claim this honor.", completion = "What is it?", objectives = "Speak with Stormrider Bruelda in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84909] = { id = 84909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghostly Celebration Crate", description = "<The crate emits a ghostly glow, and you can't help but feel the presence of mysterious spirits. Alyx would appreciate the supplies returned.>", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me.", objectives = "Return the Ghostly Celebration Crate to Alyx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84910] = { id = 84910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tabiqa", description = "My followers long for the days when they were oracles. They yearn to hear the Song of K'aresh. I am a realist. The evil of the Ravel, of Dimensius--they have destroyed the beauty that was our Worldsoul.\n\nBut you have gathered the items for the Tabiqa. So I will attempt it. When I hear the void of K'aresh's absence, there will be consequences.", progress = "It has been too long since we were this close to K'aresh. It is but an echo of what once was, but the memories that it brings back...", completion = "And the pieces fall together. Perhaps we have enough strength to take on the Shadowguard, my champion.\n\nLet me tip the scales further. With the power of these Reshii Ribbons,  I will infuse these Reshii Wraps with enough to empower you to explore Untethered Space... and gather strength for the fight ahead.\n\nYou're welcome.", objectives = "Help Soul-Scribe with the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84912] = { id = 84912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Show Must Go On", description = "Thank you for coming! We've had a bit of a mishap with the script and various stage props.\n\nThey've all gone missing! It seems as though a prankster has decided to make a mockery of our productions and scattered several needed items throughout the area.\n\nAt least the prankster was somewhat considerate and left us some clues as to where we can find the missing items. Do you think you can solve the riddles?\n\nAnd please, do not carry any open flames or shine any bright lights while in our theater.", progress = "Use the play list to find the missing items in the area.", completion = "The theater thanks you for your valiant efforts this day!", objectives = "Help Dapperdew at the Amphitheater in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84914] = { id = 84914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valorstones", objectives = "So helpful! Kobolds thank you. Earthen thank you. The Assembly thanks you! \n\nCandle for you! No better reward than that!\n\nNo, this candle not made from earwax. Made from beeswax! Smells so nice! You like nice smells, yes? If not, might want to step away from me, ha ha ha. Sorry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84915] = { id = 84915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Dunes", description = "The deserts here were never safe, but there was still beauty--birdsong, herds of animals, and the desert would bloom from horizon to horizon after a storm.\n\nNow it's a wasteland. I barely took two steps off the docks before being chased by some monster. I need to get out there. If you could cull the worst of those creatures, I'd feel much safer.", progress = "Is it safe yet?", completion = "It seems only the most vicious creatures survive outside of the eco-domes. When we find my sister, I'll bring her back to Tazavesh where it's safe.", objectives = "Slay 8 dune creatures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84923] = { id = 84923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bird's Tale", description = "I've heard that Reshad has a new story to tell involving his bird companion, Percy. Speak with him if you would like to discover the tale.", completion = "Hello there. Are you interested in Percy's tale?", objectives = "Find Reshad near the stage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84924] = { id = 84924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bird's Tail", description = "I've told many tales in my days, but my companion Percy has a tale of his own to tell. Would you care to learn about it?\n\nI will give you a clue on where to start. From there, you must find the clues that Percy has left behind to discover his story.\n\nYou can have this feather that Percy left behind as well. Look closely and you may find more clues. Perhaps a bird of your own may help you on your journey.", progress = "Have you discovered Percy's tale?", completion = "Ah, you have returned. Let me see the clues you found...\n\nMy, what a busy bird. Percy arrived at Frostfire Ridge from a ship, where you found one of his feathers.\n\nNext, he traveled through Nagrand to Shattrath City, where it appears he may have faced some conflict!\n\nAnd finally he arrived at the Spires of Arak, where he met up with me. What an adventure for our friend!", objectives = "Learn about Percy's adventures by finding his feathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84925] = { id = 84925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallying All Rapscallions!", description = "Come one, come all, straight to Dornogal!\n\nIn addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds!\n\nPresent this brochure to Hotharn to receive a few of these, on us!\n\n- Aisha", completion = "Ah, I was beginning to wonder when the eager fighters were going to show up. \n\nHere you go, as promised. Use these when submitting Crafting Orders or when crafting your own equipment. The result will be just as powerful as what Lalandi sells over there, but these are great when you're looking for something customized to your liking. If you need more, you know where to find me.\n\nQuestions? Take them to the Forgegrounds.", objectives = "Deliver the advertisement to Hotharn at the Contender's Gate in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84929] = { id = 84929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifeguard On Duty" }
quests[84932] = { id = 84932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Legacy of Destruction", description = "Adventurer! A dragon whelpling recently showed up in the pet playground and has been causing all sorts of chaos.\n\nCould you go talk to him and see if you can sort out the issue?", completion = "Raawwwr! I will burn EVERYTHING!", objectives = "Find the dragon whelpling at the pet playground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84933] = { id = 84933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Ashes to Wisdom", description = "I will become the great and powerful Deathwing! Cower before my strength!\n\nYou there! Do you wish to join me, the next Deathwing, on an epic adventure?", progress = "I want to get followers to do my bidding! Like a cult!", completion = "Ok, I guess burning things, flooding things, and forming cults isn't as fun as it sounds... Everything that Deathwing affected is just desolate and not as fun afterwards.\n\nI'll be more like Nozdormu! He's cool and has time travel stuff!", objectives = "Show Voidfire the destruction of Deathwing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84934] = { id = 84934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Descent", description = "I realize what I'm proposing is just this side of mad. The realm of death isn't the sort of place we're supposed to be able to just visit.\n\nBut these visions that are plaguing my family... Mother's led to the destruction of Dalaran. What if Silvermoon is next? I can't afford to risk any complacency. And if there's anyone, living or otherwise, who might be able to speak to Silvermoon's defense...\n\nWell. Here goes nothing. See you on the other side?", objectives = "Venture forth into the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84935] = { id = 84935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excising the Incursion", description = "The Devouring Host must have somehow followed us here.\n\nI don't know what they could want with a place like this, but I can't imagine the Void is suddenly infused with benevolent purpose. We can't allow this incursion to get out of hand.\n\nSlay as many of them as you can manage. Enough to thin their numbers, at least.", completion = "We've made a dent, but at the rate they're pushing forward, they'll overrun the whole Maw.", objectives = "Slay aberrations of the Devouring Host in the Planes of Torment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84936] = { id = 84936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Cleanse Shadow's Stain", description = "These monstrosities certainly wasted no time once they arrived. They are snatching up souls left and right and drowning them in void magics.\n\nTake my holy symbol. It should be potent enough to drive away the shadows that cling to any lingering souls.", progress = "Are the souls here just convenient targets? Or are they what drew the Host here to begin with?", completion = "I could see the reactions from the cleansing from here. I had no idea my methods would be so ill-suited to saving the souls of this place.", objectives = "Use the Redeemer's Sigil to cleanse voidwarped souls in the Planes of Torment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84937] = { id = 84937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distant Echoes", description = "Can you hear it? There's a strange sound echoing in the distance. Given where we are, I would assume it's a trick. Or worse, a trap. But it feels...\n\nI don't know how to describe it, but I feel calmer for hearing it. Like I'm in control.\n\nThis is going to sound mad, but I think--I think we should follow it. I don't know where it could be coming from, but my instincts are telling me to trust it. We should follow its trail.", progress = "<Sylvanas eyes you up and down. She says nothing.>", completion = "Honestly, I should have known this was your doing. You have a remarkable talent for disturbing the peace. I almost have to respect it.\n\nI did not, however, expect to see my nephew. Not in a place like this.\n\nNo matter. So long as you are here, you can help clean up the mess you've made.", objectives = "Find the source of the strange melody.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84938] = { id = 84938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaos Control", description = "These are no mere embodiments of Void. They move with precision and purpose. They have taken up a defensive position within the Tremaculum. No doubt they intend to expand their presence and shore up their defenses, now that they have a foothold.\n\nAll the better. It means they will all be gathered in one place.\n\nBreak their ranks. Show no mercy.", progress = "I don't have to tell you how dangerous it would be to let outside forces meddle in the Maw for overlong. We need to excise them sooner rather than later.", completion = "You're as sharp as ever. And here I was worried years of peace might dull your wits.\n\nCome. We're not finished yet.", objectives = "Stem the tide of the Devouring Host within the Tremaculum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84939] = { id = 84939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mad Space", description = "It doesn't matter how many of these void monstrosities we kill. We have to deal with the source, or they'll just keep coming.\n\nTraveling across the rift is not an easy feat in the best of times. If we can find the places where they've been able to tear through and close them, then we should be able to cut off their reinforcements.\n\nLead the way. I'll be at your back the entire time.", progress = "This place is swarming with servants of the Void. Stay on your guard.", completion = "In a way, this is an important lesson. A true paladin can't just fight darkness when it deigns to manifest. They have to seek the source.", objectives = "Collapse 5 Unstable Void Rifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84940] = { id = 84940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friendly Competition", description = "See, Ricket offered to dig it up, but the Arathi expedition lady didn't seem too keen on that.\n\nGave 'er an earful. Could hear it from the airship. Yeesh.\n\nBargus, the earthen \"ordinant\"--whatever that means-- proposed scanning the crystal to help us \"understand it better.\"\n\nI don't need to understand it. All I need's my cut. But I'm fine layin' low and doin' what they want. \n\nGo talk to Bargus at the earthen camp. See how they're comin' along an' if we can help.", completion = "<Bargus looks up from his anvil.>\n\nAnother new arrival. \n\nHere to lend a hand to our efforts?", objectives = "Seek out Bargus in the camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84941] = { id = 84941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cave Barging", description = "Unless it is a convergence of coincidence, whoever these large outlanders are, they appear to also be interested in the crystal's signal--and the location of its origin.\n\nWe earthen do not often take stock in coincidences.\n\nEngage your defense protocols, {name}. \n\nThese outlanders are not hospitable like your people.", completion = "<Bargus looks around the crumbled ruins in the cave.>\n\nThe crystals on that tablet...\n\nIf those small crystals are the source of the new energy signature, then why do they give off a stronger reading than the larger facet on the surface?\n\nThere is something else here we are missing...", objectives = "Find the source of the energy signature.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84942] = { id = 84942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Hazard", description = "With their lesser rifts closed, the Devouring Host will be hard-pressed to muster any reinforcements. But if we don't deal with their leader, then they'll just open more.\n\nAbove, in the parapets... There's no mistaking it. I can feel a force of Void drawing everything toward it, even all the way from down here. That's where we'll find our mark, without a doubt.", progress = "All that's left to do is deal with their commander.\n\nI just really wish he'd picked a slightly lower vantage.", completion = "The bulk of the lingering threat is bound in the Tremaculum. With their commander slain and their portals shut, the natural denizens of the Maw should see to the remainder soon enough.\n\nNow begone. I have work to do.", objectives = "Slay the Living Gateway atop the Tremaculum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84943] = { id = 84943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Long Vigil", description = "If you and Arator desire something of me, it will have to wait. There are souls here that require my attention, assuming your bumbling hasn't driven them off.\n\nI've managed to track four souls that fell into the Maw without proper judgment. Correct your mistakes and help me to retrieve them, and perhaps I will find time for a chat.", progress = "I take my penance seriously, Maw Walker.\n\nUnlike you, apparently. Find the souls or get out of my sight.", completion = "I see that look in your eyes. Did you think this would be a simple matter? Not all are willing or ready to be retrieved.\n\nIt matters not. They persist, and they choose. Sometimes, that is enough to ease the pain.", objectives = "Find and calm four lost souls in the Planes of Torment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84944] = { id = 84944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preludes and Preparations", description = "As you are no doubt aware, ferrying souls beyond the bounds of the Maw is no easy task. This is not a place from whence souls are meant to ascend.\n\nOur resources are limited, but I have devised a way to ensure the relative safety of the souls I retrieve--though I will require materials. Fetch for me the reeds that grow in the silt of the Gorgoa River, soulthread from the cloaks of the wandering specters, the hide of a soul-eater... Ah. And mawrat teeth.\n\nWe mustn't forget the mawrat teeth.", progress = "Have you gathered the reagents?", completion = "It's strange. I don't know how to put it, but seeing Sylvanas like this... In a way, it's how I always imagined her.\n\nI know this is meant to be penance. And it's certainly not easy. But she seems at peace, like this.", objectives = "Collect Gorgoa Reeds, Soulthreads, a Pristine Soul-Eater Hide, and 50 Mawrat Teeth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84945] = { id = 84945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repent of the Highborne", description = "The reagents are gathered, and the lingering souls have been put at ease for the moment.\n\nWe do not have long. Stand back, while I send them to where they are meant to dwell.", progress = "<Sylvanas stands silently.>", completion = "It is done.\n\nThere will be more tomorrow, and tomorrow. Until only I remain.", objectives = "Observe the Ritual of Sending.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84946] = { id = 84946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning to Life", description = "When I decided to come here, I have to admit that I wasn't sure what I would find. There's no disputing the terrible things that Sylvanas has done, and it's a burden that she will have to bear for the rest of her days.\n\nBut seeing her, like this...\n\nCome. We've been here too long as it is. The weight of this place is starting to get to me.", progress = "Let's make haste. We don't belong here.", completion = "<Arator lets out a large sigh of relief.>\n\nIt's like I can finally breathe again. I can scarcely believe that you're able to traverse that place for extended periods of time. And here I thought Uncle Khadgar was exaggerating, in all his grand tales of your adventures.", objectives = "Return to K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84947] = { id = 84947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Determination", description = "Hold a moment.\n\nArator will be fine for a few moments longer. Let him travel alone for a moment.\n\nI wish to speak to you. Privately.", progress = "It would be unwise to linger here.", completion = "Needless to say, you and I have not always seen eye to eye. All the same, I owe you thanks. Arator is a naive fool, but he is family.\n\nNow go. See to it that he returns home safely.", objectives = "Speak with Sylvanas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84948] = { id = 84948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contract Work" }
quests[84949] = { id = 84949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eleventh Hour", description = "It's high time we got back to Azeroth. I think we've done all we can do when it comes to mustering the Windrunners for whatever is to come.", progress = "We should get going. I've done enough dimension-traveling for one day, I think.", completion = "Thank you for accompanying me on this adventure, {name}. It got a bit out of hand, but I think it was worth making all the same.\n\nI hope that the warnings we dispensed were enough. Now that Xal'atath has her army and the power of a Void Lord, I can only imagine what terrors she is planning to enact.", objectives = "Return to Vereesa in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84955] = { id = 84955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contraband Banned" }
quests[84956] = { id = 84956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shadowy Invitation", completion = "The Shadowguard will stop at nothing to revive the Void Lord, Dimensius. And we should be concerned--my home was sundered by the monster. It is no mystery on how things will end if it is not stopped.\n\nHowever, I have been working on a plan... a contingency really, and it is now time to put it into motion.", objectives = "Meet Locus-Walker at the Foundation Hall in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84957] = { id = 84957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Veiled Market", description = "I have been retained by the K'aresh Trust--a coalition of both broker and ethereal cartels who seek to reclaim K'aresh. The Trust is in desperate need of one of your skills, {name}.\n\nThe Shadowguard assaults our city and threatens the work of the eco-dome project.\n\nPlease accompany me.", completion = "Welcome to Tazavesh, both of you.\n\nWe have much to discuss. Your assistance is crucial, as always.", objectives = "Accompany Locus-Walker and Alleria to Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84958] = { id = 84958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts Unbound", description = "I am Ta'ka, supplier of rare creatures destined to repopulate my homeland.\n\nAt least, I was until some of them escaped their translocation cages! This cannot stand!\n\nThese creatures are vital. If you could assist me with capturing them, I'd be quite appreciative.\n\nEngage them in combat and subdue them. The capture device I've provided will automatically translocate them back to my care once they are on the verge of defeat.", progress = "Have you finished capturing the escaped beasts?", completion = "You've returned them! Excellent work. \n\nHere is your reward, as promised.", objectives = "Defeat escaped creatures in Tazavesh to return them to Ta'ka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84959] = { id = 84959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Lines of Defense", description = "This is not a good day! Not at all. My whole shipment of barrier projectors was ransacked! Most of them are gone, and it seems whatever the culprits didn't take, they destroyed.\n\nThese barrier projectors are essential for securing the wild places on K'aresh, and even the city of Tazavesh. Our efforts are in jeopardy!\n\nPlease, if you can find any of my shipments it would help us get our efforts back on track.", progress = "Have you located my barrier projectors?", completion = "Excellent! With these projectors, we can once again secure our homeland. \n\nAnyway, you have my thanks for your assistance.", objectives = "Collect 8 Stolen Barrier Projectors for Ba'ver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84960] = { id = 84960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkness Among Us", description = "Alleria, {name}... Have you sensed it? The Void lingers in all of this. Whoever is pulling the strings is cloaked in shadow, hiding from us.\n\nCome, let's seek them out and drag them into the light before they strike.", progress = "We need to find the hidden Shadowguard, {name}.", completion = "The Shadowguard! Of course those void-addled fools are behind this. I should have known.", objectives = "Investigate the Void Presence and locate the culprits behind the many troubles in Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84961] = { id = 84961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barriers to Entry", description = "Those barrier projectors we recovered? We need them now. Place them at key points to reinforce the city shield and block more portals from forming.\n\nMove swiftly, {name}. This may be our only chance to stop the Shadowguard from flooding in.", progress = "Did you place the barrier projectors? We need to slow down the invasion. Quickly!", completion = "Well done. The shield around the city looks stronger already. \n\nThat should buy us some time against the Shadowguard.", objectives = "Place 8 Barrier Projectors around Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84962] = { id = 84962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exigent Extermination" }
quests[84963] = { id = 84963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing the Shadows", description = "No, no, no! The Shadowguard are ransacking the city and our defenses are crumbling! We even invested in new security golems after the city was last breached, but we haven't had time to activate them.\n\nWait... I have an idea. The Shadowguard--some of them must have looted entropic cores that we can use to activate the golems. \n\nPlease, you must take them down and retrieve those cores. We need to get those golems online to protect our investments! Uh, I mean, our city!", progress = "Got those cores that Om'en wanted?", completion = "These look like they're in good condition! Okay, let's go ahead and move on to the next phase of this plan.", objectives = "Collect 5 Saturated Entropic Cores from Shadowguard within Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84964] = { id = 84964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroes Among Shadow", description = "{name}! These people may not be my own, but we cannot stand by while the Shadowguard cut them down. You and I, we can make a difference! \n\nWe need to get out there, rescue the civilians, and bring them to safety. The city may be in chaos, but we can still be the shield they need.", progress = "The people are still out there, {name}!", completion = "Good. We made a difference here!", objectives = "Rescue 8 Tazavesh Civilians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84965] = { id = 84965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Core Contributions", description = "The entropic cores we collected will be crucial in our defense.\n\nUse the entropic cores to activate the market guardians scattered around the city. Once reactivated, these golems will join our fight and help us push back the invaders.\n\nTime is of the essence, {name}. The fate of Tazavesh rests in your hands.", progress = "Any of the guardians we activate should help stabilize the situation.", completion = "Excellent! That'll go a long way toward securing the city.", objectives = "Activate 5 Market Guardians scattered around Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84966] = { id = 84966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break the Assault" }
quests[84967] = { id = 84967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadowguard Shattered", description = "The commander of the Shadowguard, Shadowlord Al'zar, has assaulted this shelter of the Trust. I am preoccupied with assisting these injured brokers. I dare not leave, or their soul's energy will pour out.\n\nI must depend on you, {name}. Venture forth and eliminate Shadowlord Al'zar. His demise will cripple the Shadowguard's assault on Tazavesh. \n\nThe fate of the city rests on your shoulders.", progress = "Go. We will come as soon as we can.", completion = "Without their leader, the Shadowguard's assault on Tazavesh is crippled! For that, you have my gratitude.\n\n<He pauses for a weighty moment.>\n\nHowever, do not let this victory lull you into a false sense of security. There are darker forces at play--far more dangerous than the Shadowguard. \n\nTo resist them, we will need every advantage we can get... even those we would normally not consider.", objectives = "Kill Shadowlord Al'zar in Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84971] = { id = 84971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Love of Grog" }
quests[84972] = { id = 84972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chipping the Void", description = "Greetings. I am Driruj. I think you could help with a project of mine. \n\nThe nearby expanse of purple-hued crystal is ripe with potential. The void-infused glass could have many uses, from being a spell reagent to being melted down for crafts. I can't get near it myself, but someone like you will have no trouble at all!\n\nBring me back some samples of the void glass so I can assess their worth to future buyers.", progress = "I am preparing to move off world before what's left of K'aresh crumbles away. There are many potential uses, and therefore potential markets, for this newly created void glass. \n\nPotential equals profit, and profit means I can make a new life on a less volatile world.", completion = "Well? Let me see what you procured.", objectives = "Collect 6 Void Glass Samples from the Clefts of Unreality.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84973] = { id = 84973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Motes and Husks", description = "Regrettably, the void glass was too unstable. However, I have another idea. I believe I can stabilize the glass, but only at the moment of its creation. First, I need motes from the wyrms outside the eco-dome to power my device.\n\nWhile you're out there, hunt down some of those krolusks as well. Their husks can be ground down to make a pleasing beverage for which the folk in Shattrath will pay the highest of prices.", progress = "Anything can be turned into profit, if you have the right market. It's all about knowing your buyers and finding that which they most desire. \n\nI still think the void glass will be the most lucrative for me, but it needs to be able to hold together more solidly.", completion = "Ah, you return with motes and husks for me?", objectives = "Collect 4 Dune Wyrm essences and 6 Krolusk shells.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84974] = { id = 84974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shards of Hope", description = "I still believe void-infused glass is my ticket out of here.\n\nThe problem lies in the creation process itself. The motes you brought me can help stabilize the glass with the help of void energy. Lucky for us, there are numerous void surges on the edges of the glass crevasse.\n\nI have charged a device with the motes. All you need to do is channel void energy through it! Stand where a surge is about to happen and then collect the glass that's formed. Easy! Oh, it might tingle a bit...", progress = "There are many potential uses, and therefore potential markets, for newly created void glass. If we can get this right, I should be set up comfortably in a new home by week's end!\n\nIf you hold the device while standing in the void surges, the energy from the motes should help create more stable fragments.", completion = "Well? Let me see what you procured.", objectives = "Collect 20 Void Shards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84985] = { id = 84985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Ready on Set", description = "Oh {name}, I am glad to see you again.\n\nMy superiors have informed me that I'm responsible not only for the guests here, but for everyone putting on celebrations!\n\nNow I'm hearing that Dapperdew in Ardenweald is trying to put on a new play and running into problems.\n\nWould you mind checking in on the situation? I can hardly manage this celebration, let alone whatever is happening in the Shadowlands.", completion = "Welcome! Are you here to help with the stage preparations?", objectives = "Find Dapperdew in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84993] = { id = 84993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devourer Attack: The Oasis" }
quests[84994] = { id = 84994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evidence of Effect" }
quests[84995] = { id = 84995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pictures! Pictures of Undermine!" }
quests[84996] = { id = 84996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereesa's Tale", description = "We came here so Vereesa could get closer to the source of her visions. Unfortunately, it has only made them stronger, not clearer.\n\nBut this is her story. She should be the one to tell it.", completion = "This seems a fitting place to honor my late husband, Rhonin.\n\nWe should get on with the ceremony.", objectives = "Hear Vereesa Windrunner's tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84997] = { id = 84997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Might Come", description = "Thank you for coming with us, {name}. I'm long overdue in saying goodbye to my dear Rhonin.", completion = "Ugh... <Vereesa doubles over.>\n\nForces of the Void... attacking. Why here... now?", objectives = "Witness Vereesa's ceremony.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84998] = { id = 84998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringer of the Void", description = "Go with... Arator. Slay... their leader.", completion = "The pain is easing a bit, but I still need a moment.", objectives = "Slay Voidbringer Aqu'lir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85001] = { id = 85001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings Be Upon You", description = "These innocents were simply trying to clean up the ruins, but the cultists are slaughtering them. We must come to their aid!\n\nChampion, I am certain that you and I can do this if we work together.", progress = "These poor souls are imperiled through no fault of their own!", completion = "I'm unsure why these cultists are coming after my family, but they won't succeed!", objectives = "Help Arator to rescue 8 Dalaran Custodians from the clutches of the Twilight's Blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85002] = { id = 85002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off to Tazavesh", description = "It's imperative we seek my mother's counsel. But before we can do that, we'll have to find her.\n\nLast I heard, she was out hunting in the Great Dark Beyond on a world known as K'aresh.\n\nLucky for us, I thought ahead and asked Khadgar for a portal scroll to go directly there. I'll meet you on the other side.", completion = "Thank you for coming with me, {name}. I know I have much to learn. I'm just trying to live up to the family name.\n\nNow all we have to do is find my mother on this shattered world.", objectives = "Regroup with Arator in Tazavesh, the Veiled Market, on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85003] = { id = 85003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Operational Efficiency", description = "Locus-Walker was brought into the Trust to handle such a violent crisis of the Void. He says you are some kind of hero or champion. Good. We are in need of such a thing.\n\nTazavesh is under threat from the Void. The Shadowguard! They threaten the work of the Trust and my reputation as an administrator.", completion = "All the problems are solved. At least, all the problems that were on my ledger that I was responsible for.", objectives = "Help the brokers of Tazavesh by assisting with their issues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85005] = { id = 85005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Radiant Call", completion = "I see you received my message {name}, wonderful! We can always use more capable soldiers among the ranks of the Flame's Radiance.", objectives = "Meet Mylton Wyldbraun at the Flame's Radiance camp in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85006] = { id = 85006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those We Have Lost", description = "Ah, traveler! This was one of the first locations to show a response to our attempts to rejuvenate the land. We're actively studying why it happened at this location in particular.\n\nI have another experiment I wish to run, but I need some extra sources of power. The souls that litter the dunes are unfortunately lost, but we may let them serve one last time by using their energy.", progress = "How did the collecting go?", completion = "Ah, yes. This should be enough to cover what we need for my next step.", objectives = "Collect Flickering Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85007] = { id = 85007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extended Reach", description = "I'm very curious on why the influence of this restoration stopped where it did, as are my fellow colleagues. We set up some devices at the edge of the dunes to track the fluctuation in various energy types.\n\nThey have probably sat out there long enough for an initial reading. Could you go gather that info for me?", progress = "Hopefully the devices were easy to find?", completion = "Hmm... Nothing here seems out of the ordinary...", objectives = "Gather readings from the Broker Pylons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85008] = { id = 85008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machinations of Memory", description = "Well, the readings aren't anything to be concerned about...\n\nSo we'll move on to the next step of my experiment. This console here is the central piece of our system to rejuvenate the area. I'm hoping that if we hook it up to a significant charge, it may stabilize the area even more. Could you help me set up the energy containers as I adjust the machine?", progress = "Yes?", completion = "Fascinating! It worked!\n\nWe'll need to run some immediate tests.", objectives = "Interact with the console.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85009] = { id = 85009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those We Have Yet to Save", description = "The fauna here seem to be the same in shape as what would have been found nearby when K'aresh was still intact, but they are acting rather oddly for their species.\n\nI wonder if we could give them one last push and fully bring them into being. Take the last of the energy. I have a device that should let you channel it into them.", progress = "Have you finished our experiment?", completion = "They... dissipated? No, no, no. That can't be!\n\nSurely something in my calculations is wrong! We probably just disrupted them instead of helping them!", objectives = "Recharge 6 Flickering Ephemera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85011] = { id = 85011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where in K'aresh is Alleria Windrunner?", description = "While you were on your way, I took the liberty to ask around. These brokers seem friendly enough, but be warned... part of the city is still under attack by a group of ethereals known as the Shadowguard.\n\nI managed to get a lead on a few traders who might have crossed paths with my mother recently.\n\nWe should go before her trail runs cold.", progress = "<Umbric looks at you with curiosity.>", completion = "If Vereesa's vision is true, Silvermoon must be defended. The ren'dorei will answer the call. I'm sure of it.\n\nIn the meantime, let's get you to Alleria.", objectives = "Discover the location of Alleria Windrunner by asking around Tazavesh, the Veiled Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85013] = { id = 85013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkfuse Precipitant" }
quests[85018] = { id = 85018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Packets of Promises", description = "I will not wait a moment longer. I have arranged for transport outside of the dome, and it will be arriving soon. \n\nWill you meet me outside? I have one last thing I would ask of you.", progress = "Driruj is a fool! He's likely to burn through his wrappings with his hot-headedness. He'll be back.", completion = "Well? Is he ready to apologize and get back to work? \n\n<You hand him the satchel of seeds.>\n\nWhat's this, now?", objectives = "Talk to Driruj.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85019] = { id = 85019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Outcast's Request", description = "I felt it. Something happened in that dome. Something--no... someone...\n\nMy friend, I do not know your name or where you came from, but this is it! It has to be!\n\nThe ruined town of Sufaad to the southeast of here was where I resided as a Wastelander. Please go there and bring back my scepter, prayer book, and ceremonial bowl. There was no time to pack. I just ran, so the items could be anywhere within the town.", progress = "Once I have my belongings, I will be able to walk the path of the old ways. It is time to retake my true oath.", completion = "I knew it from the moment I saw you. The time is right for K'aresh to have his priests back.", objectives = "Retrieve Outcast Hizfran's belongings from North Sufaad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85020] = { id = 85020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood of K'aresh", description = "In the old days, we used certain deep-mined salts in cleansing processes and rituals. As you can see around you, mining is no longer valid, as these fragile rocks are hanging on to each other.\n\nOn the day of the Devouring of K'aresh, a never-before-seen mineral surfaced. The Blood of K'aresh is a blue mineral with some deposits to the west of here. Even though K'aresh is dying, I should follow the old traditions to the end.\n\nPlease collect deposits from sand striders or veins and bring them to me.", progress = "Although the Blood of K'aresh may not have existed prior to the Devouring like other minerals, it came from within our world and thus should still be usable for the process.", completion = "Yes. These will do. I will grind them to fine powder and use them to cleanse my items in my ritual of return.", objectives = "Collect 20 Blood of K'aresh deposits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85021] = { id = 85021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Void", description = "Now that you have brought me all that I need, the ritual of return can begin.\n\nYou see, stranger, the items you recovered were stowed in my hovel for over a hundred thousand years. The Void that surrounds us leaves its mark on everything it touches.\n\nWhile grinding the mineral removed the impurities of the Void, I still need to cleanse myself and the items. Please help me with the ritual. I do not foresee any distractions or issues. We are very close now.", progress = "Almost there, stranger... {name}. That is your name, is it not?", completion = "The ritual of return is over, but...\n\nDid you feel it?", objectives = "Help Outcast Hizfran with the ritual of return.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85022] = { id = 85022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priest of the Old Ways", description = "{name}, I suspect that a living manifestation of the Void came out of myself and the items. I cannot, with good conscience, take on the mantle of a priest of the old ways while these manifestations are out there.\n\nI have a final request for you.\n\nGo find these creatures and slay them. Then, I will be able to reassume the mantle of priest.", progress = "One step, {name}. One last step.", completion = "You have done it. Nothing I can give you is a good enough reward for what you have given me.\n\nFinally, my vision of you from all those years ago makes sense. You have saved me--my soul. \n\nThank you.", objectives = "Slay 3 void manifestations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85024] = { id = 85024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toy Trouble", description = "Adventurer, Maru is once again in need of your aid.\n\nShe has an urgent matter that she would like to discuss with you.", completion = "Yaay you're here to halp!", objectives = "Speak with Maru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85025] = { id = 85025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Toy Rescue", description = "A sneaky thief has taken some of my friends' toys!\n\nYou're a good sleufer now, right? Can you help my friend Yennu find his stolen toy? You'll find him on da Dragon Isles.", completion = "Wow you're an expert toy rescuer! Who do you fink stole the toys in the first place?\n\nWe should go through da clues you found and see if we can figure out the culprit! Come back tomorrow and we can go over da evidence.", objectives = "Find the missing toys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85026] = { id = 85026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Legends are Made", description = "There's so much to catch you up on {name}! \n\nWhere do you want to start?", progress = "Oooh, that one is my favorite!", completion = "Come back to me if you want me to set you on a different path!", objectives = "Select a Timewalking Campaign from Chromie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85027] = { id = 85027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: The Protectorate", description = "I have long been curious about the ethereals, who first came to Pandaria when the Mists parted. A mysterious group, they are reticent to speak of their history... but I am perhaps more persistent than most in my inquiries.\n\nSo! Who are these strangers? What do we know of their history? We must piece it together, it seems. \n\nBut our tale begins in Outland, where a hero joined a group of ethereals in Netherstorm to aid them with their cause.", completion = "With Salhadaar and Dimensius defeated, it seemed the largest problems facing the ethereals had at last been solved.", objectives = "Follow Cho's guidance to learn about the ethereals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85028] = { id = 85028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: The Brokers", description = "The ethereals are most fascinating indeed, but in my studies I have encountered another race of creatures who share many similarities with the ethereals. I feel we should speak of them as well--the brokers.\n\nThey share a nomadic nature, a desire to collect rare and unusual antiquities, and a penchant for trade.\n\nYet the brokers do not exist on Azeroth. Instead, they dwell in the Shadowlands... the land of death.", completion = "I find it fascinating indeed how much these two races have in common, don't you?", objectives = "Follow Cho's guidance to learn about the brokers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85029] = { id = 85029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: Locus-Walker", description = "While the Protectorate of Outland may have stopped Dimensius and Salhadaar, the Ethereum remained. And as Salhadaar had wished, they chose to embrace the Void. \n\nNot just embrace it--become it. It twisted them into shadows of themselves, consumed with the pursuit of power.\n\nBut there was one ethereal, Locus-Walker, that sought to harness the Void for more altruistic purposes. His history is entwined with an elf from our world--Alleria Windrunner.", completion = "Locus-Walker's intentions do indeed seem to be good, though there are those who question both him and Alleria to this day.", objectives = "Follow Cho's guidance to learn about void ethereals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85032] = { id = 85032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is Left of Home", description = "Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath. I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal.\n\nWe can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.", progress = "There will be a day when K'aresh is restored.", completion = "This is what we are fighting for, {name}. We can only save fragments of K'aresh, but we can prevent other worlds from sharing our dreadful fate.", objectives = "Speak to citizens of Tazavesh and members of the Trust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85035] = { id = 85035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locus-Walker, Telogrus Ranger", description = "I apologize for interrupting your conversation, mortal. But it was your discussion that drew Ve'nari's attention. She hears much, after all--especially when her name is involved. \n\nI have been sent with an object for you to deliver to Locus-Walker. He is an ethereal that dwells within Telogrus Rift. I believe the \"void elves\" of your world also reside there.\n\nThere is no need to travel. I will provide a portal to where you must go. Will you assist her in this task?", progress = "Why have the Shadowguard come here, of all places?", completion = "A delivery for me? This is most curious. Very well, let me have it then... and you have my thanks for helping fend off the Shadowguard.", objectives = "Deliver Ve'nari's device to Locus-Walker in Telogrus Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85036] = { id = 85036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veni Vidi Ve'nari", description = "A broker sent you with this device? And they were sent to you by Ve'nari?\n\nThis does not bode well.", progress = "I have much to think about, my friend--and much to add to my studies!", completion = "So Locus-Walker and Ve'nari knew each other? Are you certain, my friend? \n\nIt seems my research was not unfounded after all. \n\nI sought to expand your knowledge of the ethereals, but you have expanded mine instead! You have my thanks.", objectives = "Witness the conversation with Locus-Walker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85037] = { id = 85037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's a Wrap", description = "The possibilities have begun to narrow. We are on the cusp of victory. Are you ready, my champion, to fulfill your oath against Dimensius?\n\n<Xal'atath chuckles.>\n\nVery well. I have some promises of my own to keep. Let us formalize our defense against Dimensius by the platform toward the manaforge.", progress = "What is Xal'atath's game here? She had ample opportunity to trick us.", completion = "Stay vigilant my friend. Xal'atath's games have not yet unfolded. \n\nWe must be prepared for her inevitable betrayal.", objectives = "Speak to Xal'atath to assemble the Reshii Ribbons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85039] = { id = 85039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compromised Containment", description = "Somehow, an artifact in the Menagerie has broken open, unleashing a swarm of furious arcane creatures. They're wreaking havoc, and havoc is bad for the project. I need someone capable of getting this situation under control with no questions asked.\n\nIf you can get down there, clear your way through the creatures, and seal that artifact... I'll make it worth your while.", progress = "Have you completed your assignment?", completion = "You sealed the artifact? Excellent! The remaining creatures should dissipate in time. \n\nYou've handled the danger with remarkable skill. As promised, here are your rewards.", objectives = "Kill Arcane Creatures and seal the Unstable Artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85042] = { id = 85042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Toy", description = "Maru discovered that one of her toys is now missing!\n\nCould this be related to the other missing toys that you previously helped her friends with?", completion = "Nooo! My toy is gone!", objectives = "Speak with Maru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85043] = { id = 85043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Toy Thief", description = "My toy! It's been stolen!\n\nWe have to figure out who da culprit is before they take more toys!", progress = "Did you find my toy?", completion = "Yay! You found ALL the toys! How did dat big doggo collect so many?\n\nI'll have to go see if anymore of my toys are in da pile...\n\nThanks for all the halp.", objectives = "Discover the toy thief.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85047] = { id = 85047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pirate Predicament", description = "I was recently made aware of a small group of Booty Bay Buccaneers who have landed and set up camp just outside the celebration area to the north.\n\nPirates aren't inherently a problem, per se, but they do introduce an element of chaotic unpredictability. I know you're busy, but would you mind checking on them to see if they need any assistance?", completion = "Ahoy there! You look like a capable thinker. Got a sec to lend a hand?", objectives = "Head to the Booty Bay Buccaneers camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85051] = { id = 85051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beach Comber", description = "There's a peculiar mechanical gnome scouring the beach nearby for valuable scrap metals. I am concerned for his safety but also intrigued. I just wonder what he's trying to find!\n\nMaybe he would be willing to share anything he finds in exchange for your assistance...\n\nCould you aid him in recovering any valuable items?", progress = "Have you found any Salvageable Scrap? I'm looking for all I can find.", completion = "A strange gnome he may be, but his desire to locate, salvage, and re-purpose old items is quite commendable.", objectives = "Assist Kerchunk in his search for 24 Salvageable Scrap", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85052] = { id = 85052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lucrative Opportunity", description = "Most fortuitous greetings, offworlder!\n\nI have been stuck for an eon at this post checking manifests one after another. This is not real trade. Real trade is done on the streets of Tazavesh!\n\nIt just so happens that a contact of mine from your world was unloading waste cargo. I bought the whole supply. Expired storage contracts of some sort. However, I know better than to be trading without a permit.\n\nIt would bring good fortune to my endeavor to have your help with this. Can I count on you, {race}?", completion = "Xy'vez sent you? That little scoundrel can't even face me himself. Ha!", objectives = "Seek out Cartel Boss Xy'eolm in Tazavesh on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85053] = { id = 85053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obtaining Permits", description = "There is a difference between securing a permit and securing permission to sell in Tazavesh.\n\nXy'vez is a licensed dealer. He can buy and sell as he pleases in accordance with the authorities. However, I am glad he knows his place. If you are on my streets, you need my permission.\n\nNot everyone knows this. Cartel Ba likes to test the waters. I'll award your permission if you teach them a lesson.", progress = "Have you done what I asked?", completion = "Very well. Xy'vez is free to buy and sell whatever he pleases on my streets.", objectives = "Obtain permission for Vaultkeeper Xy'vez in Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85054] = { id = 85054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Articles of Acquisition", description = "Take this ledger to Xy'vez. Let him know I expect dinars upfront and on time. There are to be no discrepencies between my records and his, do you understand?\n\nYou may head to the market to inform him. Knowing traders like him, he'll have already found a spot to set up shop.\n\nThis venture has my blessing. Don't let it become unprofitable or we'll be seeing each other again, offworlder.", progress = "Do we have good news, offworlder?", completion = "The boss wants a high price, but it is a fair ask of a new venture. We will succeed quickly or we will fail quickly.\n\nLet's get to work.", objectives = "Return to Vaultkeeper Xy'vez in the market of Tazavesh on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85055] = { id = 85055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expired Goods", description = "Now then, on to business. I hear tale that your world is full of heroes on adventure. And where there's adventurers, there's need for storing their treasures. Always.\n\nThus, you have turned to our kin to keep them safely deposited between realms. Yet not one of you read the contract. We have since ceased such services and returned goods to their owners. \n\nYou and I, {name}, are selling opportunities to purchase what remains. Blind of course. Help me prepare.", progress = "Always so much to prepare before a first sale.", completion = "Excellent! With that out of the way, we can begin sales.", objectives = "Help Vaultkeeper Xy'vez prepare the void storage vaults for sale in Tazavesh on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85059] = { id = 85059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Piece of the Action", description = "Game on table look like fun. But Skaggit no want Jack to play. Maybe you can?\n\nSneak in and put a bet down. We see who wins!", progress = "Did you put down a bet?", completion = "Jack know you could pick winner!", objectives = "Contribute to an event on the Siren Isle Command Map.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85060] = { id = 85060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirate Foods and Superstitions", description = "Our trusty cook, Cooktholomew, was lost at sea. Quite tragic that was, but now all the more tragic for us here! We don't dare set sail again without the lucky feast ol' Cooktholomew would prepare for us before each voyage.\n\nWe've tried to make out his scribbles, but alas, we only managed to make the ink run.\n\nMe matey here swears he heard Cooktholomew say once he only brought copies out to sea. If that be true, the originals must be back in Booty Bay, somewhere near his bunk!", progress = "Cooktholomew and I have spun many a yarn talking about words and language. He was a lot deeper than most folk around here gave him credit for.", completion = "<Scowling Rosa looks over the notes.>\n\nThis looks like a simple enough substitution cipher. It will take me about a day or so to work on it, so I'll hold onto it and send you word when I have something for you.", objectives = "Help the Booty Bay Buccaneers figure out how to recreate Cooktholomew's lucky feast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85071] = { id = 85071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skyrocketing Sprint", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85075] = { id = 85075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Stormsong", description = "We have need of more species to help pollinate. I have studied your world, and I believe your bees in Stormsong Valley will be best. Not the fire ones though. Too dangerous. \n\nBring back some bees and we can see if they are suitable. Take this communicator in case I need to contact you.", progress = "Where did you come from?", completion = "Random people appearing from thin air was not what I had on my list of expected interactions today.\n\nStill, you look capable. Perhaps you'd be interested in helping me out here?", objectives = "Travel to Stormsong Valley in Kul Tiras to get some bees for Ve'nari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85076] = { id = 85076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Bee Crazy", description = "Something is agitating the bees, and I suspect it's these honey-crazed maulers!\n\nTake some down and see if it helps. \n\nEven if it doesn't, you're doing the world a favor. They are completely out of control!", progress = "The poor bees...", completion = "Good job. I mean, it didn't help. The bees are still upset.\n\nBut you did make the world a safer place, so credit where credit is due!", objectives = "Slay 10 maulers in the Highland Flats and Mildenhall Meadery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85077] = { id = 85077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sticky Fingers", description = "Stormsong has some of the biggest and best pollinators on Azeroth--when they aren't angry at least. If you are looking to take these, you'll need to try to calm them down.\n\nIt looks like their honey is being stolen. Try to take some honey back from those honey... blob... things?\n\nCan't hurt right? Sorry. I'm more of a plant person than a bee person. They just come with the territory!", progress = "Did you get the honey?", completion = "<Alaenra looks at your very sticky fingers.>\n\nWell done! I... shan't shake your hand though. Just well done.\n\nUnfortunately, the bees are still very upset. Still, we might find a use for the honey later?", objectives = "Collect 7 Honey Globules at the Mildenhall Meadery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85078] = { id = 85078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bee in the Bonnet", description = "While you were out, I scouted some of the smaller bee hives. They all look like they've suffered damage. \n\nWe should investigate them. Maybe that's the cause of their aggression?", progress = "What could have driven something to destroy so many hives?", completion = "Oh no--the poor queen bee! We have to save her!", objectives = "Investigate 4 Bee Hives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85079] = { id = 85079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Such a Sleebee-head", description = "We need to deal with the hive guardians one way or another if we are going to investigate this place. \n\nI do hope we don't have to kill them.", progress = "We should keep as many bees alive as possible.", completion = "Bees are super pollinators. It's incredibly unfortunate they are so murderous right now. Normally, they are quite calm!", objectives = "Tranquillize or slay 5 Hive Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85080] = { id = 85080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Un-Bee-lievable Solution", description = "If we can save the smaller bees, they can join the queen's colony. I just wish we had some way of capturing or transporting them. \n\nDo you have any ideas? Perhaps that friend of yours has something?\n\nIf you come across any of the larger bees... I worry they may be beyond saving. Do what you have to do.", progress = "Have you rescued the bees?", completion = "That was an extremely unorthodox method of capturing bees. But it was a successful one!", objectives = "Collect the Anima Vacuum and use it to vacuum up 15 Honey Bees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85081] = { id = 85081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beehemian Rhapsody", description = "We need a way to lure out the queen so we can take her away from here. \n\nOh! The honey you gathered earlier! Put that out to lure her, then catch her in this ventilated jar. \n\nYou said you were after bees? I think she'd be a great fit.", progress = "If we can get her to safety, and bring some of her hive, they can rebuild.", completion = "We saved her! \n\nLet's take her to... K'aresh was it? Always nice to see new parts of Azeroth.", objectives = "Place the Honey Pot and use it to lure out and rescue the Queen Bee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85082] = { id = 85082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To K'aresh", description = "We've secured the queen and apparently sent some bees to K'aresh. \n\nSo... How do we get there?", completion = "Congratulations. You have secured the bees, after much delay. They are in the Atrium.\n\nOnce the queen bee is delivered, we may begin our research.", objectives = "Return to the Oasis on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85083] = { id = 85083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Photogra-Bee", description = "The bees seem to be doing very well in this new environment. They are even starting to pollinate the plants here.\n\nWe should document it. It's not science if you don't write it down. You'll find them mostly around the plants.", progress = "Have you documented the bees?", completion = "Have you thought of getting into science yourself? You're a dab hand at it.", objectives = "Document 10 Honey Bees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85084] = { id = 85084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bee Strong", description = "It's taking the hive a while to get up and running, and they are low on honey. \n\nThankfully, you gathered plenty of honey back in Stormsong! Could you feed the queen?", progress = "I think the bees will do well here.", completion = "Look at her. She's so happy not worrying about those horrible death bees.", objectives = "Feed the Queen Bee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
