quests[85108] = { id = 85108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of the Trust" }
quests[85109] = { id = 85109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the K'aresh Trust", description = "Traveler, your aid to K'aresh will never be forgotten. You have our deepest gratitude.\n\nAs a token of our appreciation, we have prepared a gift for you. Seek out Om'sirik in Tazavesh. He will see that it reaches your hands.", completion = "Our thanks, traveler. May this serve you well.", objectives = "Speak with Om'sirik in Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85113] = { id = 85113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Storm's a Brewin" }
quests[85151] = { id = 85151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Her Shadow", description = "The two of you fell into the trap I set for Shadowlord Vesheen. I need to know what his orders are from Salhadaar and what he knows about Xal'atath's plans.\n\nNow, the three of us are going to sneak into this camp and see what we can discover. We're not here to fight--just some reconnaissance. I don't want him to know that I'm after him.", completion = "Now that we know where he's headed, I need another trap. A cage will do this time for what I have in mind.\n\nAnd, I know just the person who can get us one.", objectives = "Sneak with Alleria through the camp at the Fracture of Laacuna to uncover clues about Shadowlord Vesheen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85155] = { id = 85155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do You Have a Spare?", description = "Now that we know where Vesheen is, I need a cage to put him in so I can get my answers. And I know just the person who will provide us with one.\n\nVe'nari.\n\nYou'll find her in the eco-dome called the Oasis. It's on the island off to the east. Do what you must and don't take no for an answer, {name}.", completion = "{name}, it is good to see you again. What brings you to our majestic--and might I add very expensive--Oasis?\n\nStaying out of trouble?", objectives = "Travel to the Oasis and convince Ve'nari to provide you with a cage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85174] = { id = 85174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Out There", description = "You all saw what Gallywix can do. These weapons, this Black Blood--we have to cut him off at the source. Revilgaz, you've gotta kill their shipments coming out of your HQ. And Grimla, Venture Co. has to be involved for Nikki the Fixer to be so well-armed. Split up.\n\n{name}, I want you with me. I've got a newsman, Dirk, you'll want to talk to in Tailgate Park. We'll need hearts and minds to take back this city. I'll be there soon.", completion = "It's bedlam out here! But if Gazlowe's got a plan, I'm with him!", objectives = "Speak with Dirk Greasedealer in Tailgate Park.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85184] = { id = 85184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repossession is Nine-Tenths of the Law", description = "A cage you say? Of course, I have one. But, it's not free. I'll need something in return. Several somethings.\n\nI believe the saying in your world is, \"You scratch my back, I'll scratch yours.\"\n\nTo my point, there are Wastelanders occupying the nearby ruins. They are illegally hoarding relics of historic importance which belong to all the K'areshi.\n\nI want you to repossess them. Take my portation tags to make it all easier. However else would you carry so many? Your backpack isn't that big.", completion = "These will do nicely. I will speak with my associate in the... preservation society so that we might come to a mutually beneficial conclusion to this matter.\n\nHere's your cut.", objectives = "Use Ve'nari's portation tags to repossess 10 Ancestral K'areshi Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85185] = { id = 85185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those As Well", description = "There are any number of stolen smaller, but still significant artifacts in the ruins at North Sufaad. While you're out there, I see no reason why you should not also retrieve them for me.\n\nI'm certain I can make the transaction worth your time.\n\nI trust this isn't beneath you... so long as the payment is sufficient.", progress = "These lesser artifacts can also be of great importance. To the K'areshi people, of course.", completion = "What would we be if we lack our history and culture?\n\nI shall now recompense you for your munificent contribution to the enrichment of the K'areshi--and myself, of course.", objectives = "Recover 6 Lesser K'areshi Artifacts from Wastelanders at North Sufaad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85186] = { id = 85186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cage for Alleria", description = "I do so love a bit of intrigue. Please hurry back and let me know how everything plays out with this new Shadowguard lieutenant.\n\nActually, I might just come pay you a visit.\n\nI'm sure Alleria will get all the answers she's after this time...", progress = "Do you have the cage? I hope Ve'nari didn't make you jump through too many hoops.\n\nNothing's for free with her. Nothing.", completion = "Say what you will about her... Ve'nari thinks of everything.\n\nTeleporting Vesheen into this cage will make things much easier.", objectives = "Deliver Ve'nari's Package to Alleria at Shan'dorah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85189] = { id = 85189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Day in Court", description = "Another series of miscellaneous and legally questionable tasks done well, {name}! You should really consider going into this line of work full time... whatever line of work this is exactly.\n\nI'll grab the Gnomes's signatures, and meet you back at my office.\n\nNormally I'd be willing to give you a ride, but I've got a personal errand to run first. You'll see.", completion = "We're sure in the final stretch now.", objectives = "Meet Marty Zoomcart at his office in Hovel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85190] = { id = 85190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Settled Dust", description = "I'm surprised Shaw showed up in person. I thought he'd send an agent or somethin', but... maybe I should start expectin' better of people.\n\nI made sure Renzik got looked after. Got the respect he deserves. This chest took me a long time to make. A lot of tiny tools. I'm not used to detail work like that, but I got it done pretty good.\n\nI'm sure he could still pick the lock like nothin', but...\n\n<Gazlowe smiles sadly.>\n\nLet's get him sent back home to Stormwind, yeah?", completion = "I apologize for the sudden change of scenery, but it's important that you see this rather than just hear it.", objectives = "Speak to Gazlowe to return Renzik's ashes to Mathias Shaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85191] = { id = 85191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut After Cut", description = "Renzik was one of my finest agents--but more than that, he was a friend.\n\nHe wasn't an agent of the Stormwind crown begrudgingly fulfilling a mission in Undermine. He worked for Stormwind, but he loved Undermine.\n\nHis people were his home. Not us.\n\nHelp me gather up some of Renzik's things he left here. They should go back to Undermine, along with him.", progress = "Renzik never opened up all the way, but I saw what I needed to through the cracks.", completion = "Renzik grew to admire Stormwind and what we stood for, but Undermine was always what he loved most.\n\nIt's important to me that you both know that.", objectives = "Collect Renzik's belongings around the Westfall Lighthouse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85192] = { id = 85192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coming Home", description = "Renzik would want his ashes returned to Undermine. I know that for certain, and I would like to do my friend one last favor by seeing it done.\n\nI'm sure he'll like it far more than being stuffed under a marble slab in the Stormwind cemetery, far away from his people.\n\nLet's go, {name}.", progress = "Knowin' he always thought of Undermine as a home...\n\nThat's somethin'. I could've learned a lot more from him.", completion = "Renzik's home now.\n\nWe'll make sure it never gets taken from him again.", objectives = "Meet Gazlowe and Mathias Shaw on the upper stairs of the Scrapshop in Undermine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85195] = { id = 85195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirate Gastronomy", description = "Here are Cooktholomew's notes deciphered. Even though this still looks strange, I am positive I deciphered it correctly. \n\nI was able to work out how much of everything you need, but it looks like he had his own names for different ingredients, so... good luck!", progress = "Don't ya worry. We're a patient bunch, we are.", completion = "Luck and fortune be upon us, you've done it! Now we can make our feast and set sail back home. \n\nThanks a bunch, pal!", objectives = "Use Rosa's Boonful Banquet translation notes to search for the ingredients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85196] = { id = 85196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tag, You're It", description = "Vesheen is up in the Khiyed Ruins to the north. The fool thinks he's so clever, but he's about to find out who he is dealing with.\n\nWear him down and then place Ve'nari's tag on him. It will teleport him into the cage here.\n\nI'll stay here to make sure the cage works. Hurry, {name}, before he realizes we're on to him!", progress = "He's going to tell me everything. Too much is riding on this for half measures.", completion = "You've done well. This Shadowguard scum will tell me all I need to know.\n\nOr else.", objectives = "Weaken Shadowlord Vesheen and then place Ve'nari's Portation Tag on him to teleport him into Alleria's cage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85208] = { id = 85208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pirate Missive", description = "There you are, {name}. Someone named Scowling Rosa wants to see you in Booty Bay.", completion = "I've done my best with those notes. I hope you find this helpful.", objectives = "Pick up the notes from Scowling Rosa in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85212] = { id = 85212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Void Test of Wills", description = "This will be dangerous. I intend to use the Void to break his will and extract what I can from his mind.\n\n{name}, stand ready to assist. First, we'll set up some ritual devices. Then, listen for my instructions.\n\nOne false move could mean our doom.", progress = "It seems our war against the Void is never-ending.", completion = "My mother sacrificed much by killing Vesheen. I'm sure she could have extracted more information out of him.\n\nMaybe I've been too hard on her.\n\nNow to decide what's next. I hope you'll continue on with me, {name}.", objectives = "Assist Alleria in her void contest to break Shadowlord Vesheen's will.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85213] = { id = 85213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off to Tazavesh, Again", description = "Now that we've helped my mother, it's time to continue on.\n\n<Arator seems choked up at the idea of leaving his mother again so soon.>\n\nVe'nari helped us before. I know it's dangerous, but maybe she can get us into the Maw to find Sylvanas?", progress = "Well, hello there. Again.", completion = "What you ask is both difficult and, as you well know, potentially deadly for Arator. He is no Maw Walker, but you are.\n\nRegardless, I will help you to get there if that is your wish.", objectives = "Work with Arator and Ve'nari to decide how best to proceed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85214] = { id = 85214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Here Goes Something", description = "Getting you into the Maw to visit his auntie, Sylvanas, can be done... but at no small risk to Arator. Under no circumstance should he linger there.\n\nHowever, that is your business. I am in the business of keeping my slates clean, and this is something I can do for you.\n\nThe engine of Tazavesh can power a gateway and allow the two of you to break into that dreadful place.", completion = "{name}, the forces of the Void slipped through the gateway!", objectives = "Use the power of the city to open a gateway to the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85229] = { id = 85229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallying All Rapscallions!", description = "Come one, come all, straight to Dornogal!\n\nIn addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds!\n\nPresent this brochure to Hotharn to receive a few of these, on us!\n\n- Aisha", completion = "Ah, I was beginning to wonder when the eager fighters were going to show up. \n\nHere you go, as promised. Use these when submitting Crafting Orders or when crafting your own equipment. The result will be just as powerful as what Lalandi sells over there, but these are great when you're looking for something customized to your liking. If you need more, you know where to find me.\n\nQuestions? Take them to the Forgegrounds.", objectives = "Deliver the advertisement to Hotharn at the Contender's Gate in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85238] = { id = 85238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger on the Steps", description = "Please! We have to stop the Naakroans. Three of us were sent by cartel Om to install a research machine. It was only meant to help study extinct plants. At first, the Wastelanders were polite, even curious--until we tried to leave. \n\nThey forced us to modify the machine. Om'musa refused and they killed him. Om'baladh and I obeyed. We should have refused as well.\n\nOnce we finished, the Wastelanders let their guards down. Om'baladh said to run, so I did. He was right behind me. Please--find him.", progress = "Oh, my friends. What have we done?", completion = "I heard him fall. I should have stopped for him. Instead, I kept running.\n\nWe have to make this right. We turned the machine into a weapon for the Wastelanders. It won't help rejuvenate the land--it will kill everything.", objectives = "Find Om'baladh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85239] = { id = 85239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Devouring", description = "This isn't a temple anymore--it's an abattoir. They tear souls from captives to power their rituals. Right now, they're pouring stolen energy into our machine. I think I know why.\n\nWith the modifications we made, overloading the device with arcane energy will create a massive feedback loop. It'll disrupt our technomancy across K'aresh. The eco-domes will fail. Tazavesh will be defenseless. We'll be just another feast for the Naakroans. If you can disrupt their rituals, it will buy us time.", progress = "Stop the rituals. End the suffering of their captives.", completion = "That will slow them down, but I worry it's not enough. We need to end this before they destroy all of our work.", objectives = "Disrupt the Naakroan rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85240] = { id = 85240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only Hunger Remains", progress = "We won't let them take what we've built.", completion = "Even if we fail here, this might give our defenders a chance.", objectives = "Slay Naakroan Wastelanders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85241] = { id = 85241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Once-Proud Priest", description = "Their leader conducts the last ritual site. Issam the Unraveler... I saw him live up to that name. If he uses our echo machine against us, he and his followers will tear through everything. We'll all be offerings to their absent \"god.\"\n\nSlay him and end his ritual. We can't allow a second Devouring.", progress = "Killing him should stop the ritual. It has to.", completion = "No. He's dead. Why hasn't it stopped? It's only growing stronger.", objectives = "Slay Issam the Unraveler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85242] = { id = 85242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seasonal Refresher", description = "We're back tae uncovering more things within delves! \n\nLet's get ye up to speed on new items we've found first. \n\nThen I've got some concerning information tae talk about.", completion = "All set? Good.\n\n'Cause I got a story tae tell ye.", objectives = "Learn about Season 2 of Delves from the Delver's Documents, then purchase supplies from Reno Jackson and Sir Finley Mrrgglton.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85243] = { id = 85243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Want My Hat Back", description = "Ye may have noticed a change in me fashion. \n\nSome goblin went and took me hat! And all the treasures we had collected so far!\n\nI'll tell ye how it all went down.", completion = "And now ye know the whole story. \n\nBut at least I swiped the button for the buggers ride. \n\nYou take it! I got bigger things to handle.", objectives = "Listen to Brann's story of how he lost his treasures and his hat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85244] = { id = 85244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defeating the Underpin", description = "This blasted \"Underpin\" took me hat! Along with all the curios we collected.\n\nIt's time tae get some vengeance. We got tae get stronger if we're going tae take him down.\n\nI know he's somewhere in Undermine when yer ready tae tackle him. \n\nI'll be right there with you!", completion = "We did it! Hah! \n\nThat'll show the world not tae mess with us! \n\nAnd tae never try stealin' me hat again! \n\nAh... it feels so good tae have ye back. \n\nHere. Take me spare hat. It didn't feel right tae wear it while the other one was missin'.", objectives = "Increase your item level to challenge the Underpin in his tier 8 delve within Undermine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85249] = { id = 85249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bee Test", description = "I will send your... guest... to the Atrium to handle the bees.\n\nYou should check on her. No doubt she needs assistance.", completion = "Hello again, {name}! Are you here to help out?", objectives = "Meet Botanist Alaenra at the Atrium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85252] = { id = 85252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: Children of the Blood", description = "The blood elves of the Eastern Kingdoms have only taken up that name in recent years. Once, they were known as highborne, or high elves--but no more. Would that it were a pleasant tale, but in truth the name reflects upon those who have fallen and lost their lives... an unthinkable number. \n\nThe blood elves, or sin'dorei, will never forget that loss. Let us remember them as well.", objectives = "Despite all that they have experienced, the blood elves continue to stand in the face of adversity. Together, they hold strong against any who would threaten either their people, or the Sunwell that forms the cornerstone of their culture.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85254] = { id = 85254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: Children of the Void", description = "The void elves... so strange. There is very little difference between a void elf and a blood elf, other than what they have chosen to wield. Yet to their former kin, they are anathema--no longer considered a blood elf at all, and no longer welcome in their former home. \n\nLet us explore how, and why, this came to be.", objectives = "What little we know of the Void tells us that trying to master it is an exercise in futility. Yet there are those with the strength to try--and perhaps we look upon them too harshly for making the effort.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85255] = { id = 85255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tranquila-Bee", description = "I think we should start prepping to move the bees into the Oasis. I'd like to tag them so we can monitor the hive. \n\nBees don't tend to stand still for long. We'll need to tranquilize and tag them. I tagged the queen. Would you tag the honey bees?", completion = "Ah, thank you! I hope you didn't get stung!", objectives = "Tranquilize and tag 10 bees in Eco-Dome: Primus in K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85256] = { id = 85256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botany, Finally", description = "The bees are doing well and have no negative interactions with the local fauna. But what about the flora?\n\nI have some cuttings of plants from the Oasis. Would you gather some cuttings from this dome so I can compare them?", progress = "I'm terribly excited to work on plants again. It's been quite a while now. Get it? Bee-n?", completion = "Excellent! The bees and plants are getting along nicely. This means they are ready for the Oasis!", objectives = "Collect 10 K'aresh Flora Cuttings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85257] = { id = 85257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primus Buzzness", description = "Alright. Let's get these bees into Eco-Dome: Primus for the next round of tests!", completion = "If I were a bee, I'd be a queen bee.", objectives = "Meet Botanist Alaenra in Eco-Dome: Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85258] = { id = 85258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh Honey Honey", description = "The hive has settled in quite well. I'd like to do a quick honey check though. The pollen in these plants is quite different, and it should change the honey quite a bit. We need to make sure it's working for the hive. \n\nIt should be fine based on the experiments in the earlier domes. Best to check though, right?", progress = "Have you collected the honeycomb?", completion = "I'll run an analysis on this to ensure there are no issues. Thank you.\n\nAlaenra mentioned another task she had, if you have the time.", objectives = "Collect 8 Honeycombs and then pet the Queen Bee in the Oasis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85259] = { id = 85259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waggle Dance", description = "Alaenra requested that I pass on a message.\n\n\"Hey, Om'talad. I'm going to dance for the bees so they know where the new flowers are. Can you ask {name} to do the same?\"\n\nOdd, but please feel free to... frolic.", completion = "Have you bee-n dancing? You did well, {name}. This will help the bees and the Oasis flourish. More bees knowing where more plants are can't possibly go wrong.", objectives = "Dance for the bees in the Oasis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85260] = { id = 85260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hiving a Hard Day", description = "I just spotted a few bees flop to the ground. I think they've overworked themselves trying to get at the new plants.\n\nThey'll be fine. They're just tired. Could you help me pick them up and bring them back to the hive?", progress = "Poor bees! Handle them carefully.", completion = "All bees accounted for. Thanks, {name}.", objectives = "Pick up 10 Overworked Honey Bees and return them to the hive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85261] = { id = 85261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bee Roll", description = "Ah, there you are. It's time for documentation!\n\nWe need to keep track of how the bees are doing in the Oasis. I've filled out the paperwork already. Perhaps you could get me some photos of the bees in action?", progress = "Have you gotten some good shots?", completion = "You really have this photography down you know. Look at the composition of this shot!\n\nWe don't need Cataloger Wulferd levels of photos... but I do appreciate them.", objectives = "Document 10 Honey Bees and the Queen Bee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85262] = { id = 85262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Royal Procession", description = "Hmm, your photos make me think the hive is ready to swarm!\n\nThis is the ultimate goal of any hive--birth a new queen and create a new hive. It does mean our queen needs to move to a new location, but there is plenty of eco-dome to go around, right?\n\nCan you help her find a new location?", progress = "Have you gotten the old queen settled in?", completion = "Excellent--our queen is all grown up!", objectives = "Help the Queen Bee find a new hive location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85263] = { id = 85263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boomball" }
quests[85268] = { id = 85268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pow-Arr Wash Simulator" }
quests[85269] = { id = 85269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boom Balloon" }
quests[85270] = { id = 85270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cold as Ice" }
quests[85383] = { id = 85383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Applied Mixology", description = "Allow me to introduce myself, traveler. I am known as Ba'kril.\n\nAs you know, my people do not imbibe as yours do. My proposal is simple: help me concoct a new energy drink and I shall allow you to use it free of charge.\n\nIt will most certainly make you a hero amongst heroes. Is that not worth the risk?\n\nI have acquired various potent energy sources. Infuse them into the berry juice cocktail and let us see how potent we can make it.", progress = "On the soul of K'aresh, I make my oath to you, traveler. We will create the finest, most powerful infused concoction ever seen. With it, you will have the power of ten devourers!\n\n<Ba'kril grumbles something under his breath about Tazavesh's leadership.>\n\nOf course, there will be just a pinch of profit on the side for me.", completion = "Unbelievable! It worked and we were not blown into an incalculable number of miniscule pieces. I do hope this formulation proves useful not only for you, but for the future of K'aresh.\n\nNow on to phase two... testing and market research.", objectives = "Concoct an energy drink infused with various power sources.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85384] = { id = 85384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Market Research", description = "Since I never doubted our success, I took the liberty of making further preparations.\n\nI have arranged for a couple of volunteers. I want to see our new energy drink in action before you imbibe it, {name}. May I call you {name}? Of course I can. We're partners now.\n\nYou will find the volunteers lounging on the high terraces of the city. Tazavesh has many such comfortable areas for visitors like yourself.", progress = "We are both certain to profit from this venture, {name}, regardless of the outcome.", completion = "Destroy the city?! You must help me quickly and quietly deal with this... *ahem* situation, partner.\n\nHave I become that which I sought to oppose?", objectives = "Speak with the volunteers to test the new energy drink.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85390] = { id = 85390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunrise Sudser" }
quests[85394] = { id = 85394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Eye for Trouble", description = "If we were to consider the silver lining here, it is that we now know our concoction works. Just not on whom we wished.\n\nI do not suppose you have it in you to defeat this empowered version of the creature? It is only our reputations and the future of Tazavesh at stake.\n\nAnother chance to prove you truly are as mighty as they say.", progress = "Is it done, {name}?", completion = "All is not lost. This will blow over in time and I now know the drink can work.\n\nI will get it right next time, and we will have a tool in our arsenal in case another \"well-intentioned\" group like the Ravel rises again to reign destruction down upon us.\n\nI might need to lay low for a bit, but you, {name}--you are a hero! And heroes deserve rewards. Let me see here...", objectives = "Defeat Bakishroth the Empowered and save Tazavesh!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85396] = { id = 85396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heaps o' Scrap" }
quests[85397] = { id = 85397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Plants Crave" }
quests[85398] = { id = 85398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomb Voyage!" }
quests[85399] = { id = 85399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caddyshock" }
quests[85400] = { id = 85400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reduce, Re-ooze, Recycle" }
quests[85402] = { id = 85402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In The Heights" }
quests[85409] = { id = 85409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snitches Get Stitches", description = "I thought we could talk here in Gutterville, but it feels tense. They're all Venture Company, but I don't recognize a lot of 'em. Word is, Gallywix sent down a bunch of workers who are sympathetic to him so they could spy on us. \n\nClear out some of these turncoats. If any of them report to Overseer Gozzic that we're working against the pipeline, he'll go after my people.", progress = "The spies are everywhere, I tell ya.", completion = "There were more spies than I expected. It's hard to have faith in the Venture Company. But we're not all like that.", objectives = "Remove the Venture turncoat spies in Gutterville.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85410] = { id = 85410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undermine's Long Shadow", description = "These engineers have been through a lot. Let's make sure they're good. Maybe they can shed some light on Undermine.", progress = "There's a lot of information to chew on.", completion = "Our next stop should be Undermine.", objectives = "Speak with Pamsy's engineers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85427] = { id = 85427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Expiration" }
quests[85428] = { id = 85428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Code Violations" }
quests[85429] = { id = 85429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overwhelm Them", description = "There's an audit coming up. My employer, Xy Imports, will be audited. Again.\n\n<Xy'nell visibly shakes, ducking his head.>\n\nI need this audit to go badly. It must be worse than the last.\n\nCan you help me? We have a shipment of small devourers that would cause a lot of trouble if they were to escape or go missing.\n\nBreak open their crates. Business needs to be overwhelmed just like last time.", completion = "Good. Good. Things are in disarray. This is a start.\n\nPerhaps you're just the measure of mayhem I needed to pull this off.", objectives = "Break 8 Xy Imports Crates on the docks in Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85430] = { id = 85430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mandatory Time Off", description = "If my colleagues knew of my plan, they would be in danger of discharging their oaths as good employees. Besides that, they are far too excellent at their jobs.\n\nTake these. They're devices of my own creation. When placed near my colleagues, it will create an illusion of them working.\n\nThey will be able to step away and rest. And the business will be under even more pressure without them.", progress = "I had to become good at illusions for this job. It was the only way to make it tolerable.\n\nMaybe now I can use those skills to help others for once.", completion = "I'm glad none of my coworkers will have to see what we're going to do. They deserve the rest.", objectives = "Place 7 Illusion Devices.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85431] = { id = 85431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drain Their Resources", description = "We've made good progress, but we need more disorganization.\n\nI've redirected a particularly large shipment of anima in the form of a devourer. Kill it and bring its anima core to me.\n\nThe anima itself is not important--rather, the fact that it can be stolen. My boss will have more to answer for in the audit when his books are in disarray.", progress = "The Xy Imports associates transporting this anima are expecting a--ah--broker of sorts to relieve them of their charge.\n\nThey will give you no trouble.", completion = "Thank you, {name}.\n\n\n\nMore incriminating evidence for the audit.", objectives = "Collect Overflowing Anima Core from Respleth the Hungerer outside Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85432] = { id = 85432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confuse Their Contacts", description = "When our imports are delayed or lost, the most direct impact is on Tazavesh businesses.\n\nTake this illusion pin. It will make you appear as a Xy Imports employee. Tell the businesses their shipments are delayed indefinitely.\n\nMy boss cannot ignore downstream pressure forever.", progress = "This is not the first time the market vendors have dealt with my boss's failings. I only hope it is the last.", completion = "<Xy'nell's voice is rough.>\n\nWe will soon resolve their worries. Better a temporary strain than an eternal, constant stress.", objectives = "Speak with market vendors in Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85433] = { id = 85433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes on Us", description = "I can hear Coordinator Xy'thir raging about the slide in business already.\n\n<Xy'nell shifts uncomfortably and ducks his head.>\n\nWe're ready. Go to Port Authority Zo'rau. Tell them you represent an invested party and that the audit should be moved up.\n\nAnd there's one more thing I need you to do. Speak with me before you go.", progress = "This is more important than I can say, {name}. But I cannot break my oath. Deliver the pin to Zo'rau.", completion = "Zo'rau is wearing the pin.\n\n<Xy'nell's shoulders loosen.>\n\nThank you, {name}. Now you and I must be careful.", objectives = "Speak with Port Authority Zo'rau in Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85434] = { id = 85434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On a Technicality", progress = "<Xy'nell is silent before Coordinator Xy'thir.>", completion = "Thank you, {name}. Thank you for everything.\n\n\n\nNow we do the work to set the business on track again. But perhaps after a bit of rest.\n\nI... I can rest! The coordinator... he won't be able to find me.", objectives = "Confront Coordinator Xy'thir in Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85438] = { id = 85438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Or Else", description = "Am I glad I found you, {name}! \n\nMy boss, Kraz Torquewrench, sent me to find you, and he don't take no for an answer, yanno? I thought I was gonna have to cash out and move futher underground, but here you are!\n\nAnyway, the boss's little girl is getting married, and he told me he wanted you, specifically, to help him \"finalize\" some \"details,\" with her intended and who's attendin'--if you get my meanin'.", completion = "I need someone with panache who can do things fast an' quiet to help me finalize things for my little girl's big day. That's you.", objectives = "Speak with Kraz Torquewrench in Hovel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85444] = { id = 85444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Found Family", description = "This crew trusted me. They're my family. We gotta see if any of them survived. \n\nI have other engineers who ain't here. They must have fled into the field. Razi, Keets, and Glizza are out there. Find 'em. Bring 'em home.", progress = "Don't leave those engineers out there to die.", completion = "We made some progress here while you were helping Pamsy's engineers.", objectives = "Rescue Pamsy's last engineers from the Writhing Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85449] = { id = 85449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase Shift", description = "As soon as the ethereals attacked, phase resonance tore open rifts throughout the area. The rifts are gone, but the ethereals can return while the resonance remains. That is how they call more soldiers and communicate with their commanders.\n\nWe need to destroy that resonance.\n\nIt may earn us the ire of whoever is behind this attack, but I gladly invite them to stop us.", progress = "We need to destroy that resonance if we are to stop this attack.", completion = "The Dark Heart was in Undermine all this time. I should have known.\n\nIf the ethereals reach the Dark Heart before we do, all will be lost.", objectives = "Destroy 4 Phase Resonance in the Vatworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85450] = { id = 85450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evacuation Plan", description = "We cannot let the ethereals find the Dark Heart before we do.\n\nGazlowe needs to be informed. We must gather our forces and find the Dark Heart--quickly!", progress = "We need to get to the bottom of this.", completion = "If Gallywix has got the Dark Heart in his warehouse, then we need to get to that warehouse.", objectives = "Regroup with Gazlowe in Steamwheedle Laboratories.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85451] = { id = 85451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burning of Hammerfall", description = "The Syndicate has put Hammerfall to torch!\n\nAnd the cowards are using pyromancers to feed the flames.\n\nBut we can save our huts if we get to them quickly.\n\nFight through the Syndicate bandits to a building and then blow this horn. A Hammerfall shaman will come to put out the fire!", completion = "Hah! Built orc strong!\n\nJust like us!", objectives = "Use the Hammerfall Horn at each main structure in Hammerfall to summon a shaman and put out the flames.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85459] = { id = 85459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Reclamation Program", description = "The eco-domes run on anima. While you are out in K'aresh, if you see any devourers--kill them and return with their anima.\n\nYou will be compensated.", progress = "Our reserves are in no immediate danger, but it is better to be safe than sorry, is it not?", completion = "Excellent! Now I need you go and gather some stygia.\n\nIt is a joke, {name}. I can joke. Occasionally.", objectives = "Collect 20 Devourer Anima in K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85460] = { id = 85460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ecological Succession" }
quests[85461] = { id = 85461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Food Run", description = "Our latest food shipment for the animals was taken by an ethereal raid in Tazavesh. \n\nI would like you to reacquire it.", progress = "Have you acquired the food?", completion = "Your capacity for violence always brings me great delight, {name}.\n\nI am certain the ethereals do not feel the same way.", objectives = "Reacquire 15 Stolen Food Shipments from ethereals in Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85462] = { id = 85462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Challenge for Dominance", description = "Our slateback alpha has been getting a bit... testy recently. I believe he is looking for a challenge. \n\nYou are the most combat capable of us. Go give him one.", progress = "Do try to avoid damaging it permanently.", completion = "Quite a spectacular battle, as always.", objectives = "Challenge the Slateback Alpha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85465] = { id = 85465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Play Ball", description = "This thorntail kit has been begging me for attention all morning. It is quite charming, but I have work I need to get done!\n\nI think it needs to burn some energy off. Take this ball and go play with it.", progress = "<Om'talad absentmindedly pets the thorntail kit.>", completion = "Finally, I can get some work done.\n\n<One of Om'talad's four arms scratches the thorntail kit behind the ears.>", objectives = "Catch a ball 10 times while playing with your Thorntail Kit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85466] = { id = 85466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hob or Cold" }
quests[85467] = { id = 85467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dumpster Fire" }
quests[85470] = { id = 85470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Root Redux", description = "Some of the lapbugs are getting stuck in the tree roots again. If left to their own devices they will eventually eat their way out, but it would be easier if you offered your assistance.", progress = "They're very cute, but not exactly... bright.", completion = "Thank you. I would hope this would be the last time they get stuck, but we both know it won't be.", objectives = "Detangle 10 Stuck Lapbugs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85471] = { id = 85471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Gallagio Loyalty Rewards Club", description = "The Gallagio appreciates your continued loyalty!\n\nWe've got some extra supplies for only our most honored of High Rollers. Come see us for your gift!", completion = "Here you go!", objectives = "Speak with Paula Piranha inside the Liberation of Undermine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85472] = { id = 85472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Free Reagents!", objectives = "Speak with the Steamwheedle Alchemist and follow their instructions to brew a potion from scavenged ingredients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85473] = { id = 85473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extra! Extra!", objectives = "Deliver newspapers to the uninformed citizens of Undermine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85474] = { id = 85474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rat Pack Attack" }
quests[85475] = { id = 85475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret in the Sands", description = "Welcome back. Maru is looking for you again. She says only you have the skills to help her with this task.\n\n<The groans and complaints from the crowd intensify.>\n\nOh, don't worry about me. I'll be here... As always...", completion = "Hey! I have a task tat's perfect for you!", objectives = "Speak with Maru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85476] = { id = 85476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Tweasure", description = "Hello friend! You won't believe it, but I heard there's a hidden tweasure somewhere in Tanaris!\n\nI'm suuuper sneaky and managed to get a copy of the first riddle. And you're so good at solving them tat I want to give it to you!", progress = "Go find the tweasure!", completion = "Whoaa, what an awesome tweasure! I'll take tat, thanks.", objectives = "Find the buried treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85477] = { id = 85477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost and... Found?", description = "I am so overwhelmed. A group of folks were here a little while ago, all complai... I mean, submitting lost-item notices with great passion, but all at the same time. \n\nI tried to take down all the details, but in the stress of the moment, I fear they're all jumbled.\n\nI have this collection of items that have been found over the day, and I'm fairly sure these are the items those folks were talking about. Do you think you could use my notes and figure out which item belongs to each person?", progress = "How's it going? Have you found the owners of all the lost items?", completion = "Have you finished with those items? Oh, bless your heart! I'm actually quite surprised at how few people have lost things during these festivities. Still, I'm simply bursting with gratitude at your willingness to help those unfortunate few who have.", objectives = "Deliver the lost items to their correct owners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85479] = { id = 85479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock 'Em, Explode 'Em" }
quests[85481] = { id = 85481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ridge Racer", description = "Our Slateback Alpha needs to burn off some energy. I believe he is looking for a race.\n\nHe seems to enjoy you the most. Would you race with him?", progress = "Some of the brokers have placed bets for this race.", completion = "Ah, the alpha appears quite tired now. You have my thanks... and I have the winnings from my wager.", objectives = "Race the Slateback Alpha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
