quests[85500] = { id = 85500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazardous Waste" }
quests[85502] = { id = 85502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festive Reflections", description = "Oh good, you're back. I have my hands full here and Detective Jones has been asking for your help on some new case.\n\nNot that it seems to matter. For all the good we do for the guests, I think this line--if you can still call it that--has only grown longer!\n\nI should get back to it, and you should talk to Detective Jones.", completion = "Do you have a moment? We have a very special case ahead of us.", objectives = "Speak with Detective Jones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85503] = { id = 85503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Surprising Investigation", description = "Well, look who's back to solve more cases.\n\nIt seems that Chromie has been fiddling with time again and some imposters have popped up around the celebration area.\n\nAll you need to do is identify who doesn't belong and send them to Chromie. This should be a breeze for you.", progress = "How goes it?", completion = "This was quite a surprise! It's nice to get a chance to relax.", objectives = "Solve the case given to you by Detective Jones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
